// The Pathland DOM renderer bootstrap. Hydrates the server-rendered DOM,
// connects to the WebSocket, applies PLPL deltas in place, and reports raw
// inputs back as host → guest EVENT batches (gated by EVENT_LISTENERS when the
// SSR HTML carries a `data-event-listeners` mask). Bundle: dist/pathland-dom-renderer.js

import type { DomRenderer } from "./apply";
import { hydrateFitElement, refreshFitSlots, setupMediaElement, updateNavBackButtons } from "./apply";
import { Transport } from "./transport";
import { log } from "./log";
import { clearInFlightRange, markRangeInFlight } from "./inFlight";
import {
  encodeDateChanged,
  encodeEditingChanged,
  encodeEnvironment,
  encodeFocusChanged,
  encodeKeyDown,
  encodeKeyUp,
  encodeNavigate,
  encodeNavigateBack,
  encodePointerDown,
  encodePointerMove,
  encodePointerUp,
  encodeResync,
  encodeScroll,
  encodeTextChanged,
  encodeValueBits,
  encodeValueChanged,
  encodeWheel,
} from "./events";
import {
  FLAG_HOVER_ENTER,
  FLAG_HOVER_LEAVE,
  FLAG_POINTER_SECONDARY,
  LISTEN_EDITING,
  LISTEN_FOCUS,
  LISTEN_KEY_DOWN,
  LISTEN_KEY_UP,
  LISTEN_POINTER_DOWN,
  LISTEN_POINTER_MOVE,
  LISTEN_POINTER_UP,
  LISTEN_SCROLL,
  LISTEN_WHEEL,
} from "./constants";

/** The owning Pathland node (the closest `[data-pathland-id]` ancestor). */
function nodeOf(el: Element | null): HTMLElement | null {
  return el ? el.closest<HTMLElement>("[data-pathland-id]") : null;
}

/**
 * The element an input event belongs to: the nearest element (self or ancestor)
 * that has a `data-pathland-id` AND a `data-event-listeners` mask including `bit`.
 * Unlike {@link nodeOf} (which returns the deepest id-bearing element), this walks
 * up so a gesture declared on a container (e.g. a tap on a `VStack` row whose child
 * `Text` is what's actually clicked) is attributed to the node that listens — the
 * contract the GTK renderer follows (gesture attached to any widget with the bits).
 * Elements that declare no listeners are skipped, so non-listening children never
 * steal an event from a listening ancestor.
 */
function eventNodeOf(target: Element | null, bit: number): HTMLElement | null {
  let el: Element | null = target;
  while (el && el !== document.body) {
    if (el.hasAttribute("data-pathland-id")) {
      const raw = el.getAttribute("data-event-listeners");
      if (raw !== null && (Number(raw) & bit) !== 0) {
        return el as HTMLElement;
      }
    }
    el = el.parentElement;
  }
  return null;
}

/**
 * EVENT_LISTENERS gating: emit an event only if the node's `data-event-listeners`
 * mask (from the SSR HTML, mirroring the Rust renderer's event attrs) requests it.
 * When the attribute is absent there is no gating information — be permissive.
 */
function listens(node: HTMLElement | null, bit: number): boolean {
  if (!node) {
    return false;
  }
  const raw = node.getAttribute("data-event-listeners");
  if (raw === null) {
    return true;
  }
  return (Number(raw) & bit) !== 0;
}

function modifiersOf(e: KeyboardEvent): number {
  let m = 0;
  if (e.shiftKey) m |= 0x01;
  if (e.ctrlKey) m |= 0x02;
  if (e.altKey) m |= 0x04;
  if (e.metaKey) m |= 0x08;
  return m;
}

function keyCodeOf(e: KeyboardEvent): number {
  return typeof e.keyCode === "number" && e.keyCode !== 0 ? e.keyCode : e.key.charCodeAt(0);
}

function boot(): void {
  const byId = new Map<number, Node>();
  for (const el of document.querySelectorAll<HTMLElement>("[data-pathland-id]")) {
    byId.set(Number(el.getAttribute("data-pathland-id")), el);
  }
  log.info(undefined, `dom-renderer boot — hydrated ${byId.size} nodes`);
  // The reserved framework path prefix (spec — host system endpoints live under
  // `/_pathland/**`). The SSR page carries it as `data-pathland-base` so a host
  // can relocate it (e.g. behind a proxy); defaults to `/_pathland`.
  const base = document.documentElement.dataset.pathlandBase ?? "/_pathland";
  // The app's mount prefix, derived from its framework base (`/<mount>/_pathland`,
  // `/_pathland` for the root app). The server emits app-relative ROUTEs; the browser
  // URL is the app's real address, so URL mirroring must prepend the mount
  // (`/app2` app navigating to `/home` → the URL `/app2/home`). The root app (mount
  // "") is unchanged.
  const mount =
    base === "/_pathland" ? "" : base.slice(0, -"/_pathland".length);
  // Per-window identity (the server's persisted-state scope): kept in sessionStorage so
  // a reload of THIS tab keeps its state, while a NEW window/tab gets a fresh id — two
  // windows never share a UI model or state. The server reads it as the `wid` query
  // param on the WebSocket URL ONLY — it is deliberately never reflected into the page
  // URL, so the address bar/history/referrer stay clean. The SSR request therefore has
  // no wid: it renders defaults, and a same-tab reload re-syncs this window's state
  // over the WebSocket (see `onOpen` below).
  const storageKey = "pathland.wid";
  let wid = sessionStorage.getItem(storageKey);
  const isReload = wid != null;
  if (wid == null) {
    wid = crypto.randomUUID();
    sessionStorage.setItem(storageKey, wid);
  }
  // Strip a stale `?wid=` a shared/bookmarked URL may carry (from before the id left
  // the URL): the SSR already used it, so it also forces a re-sync below. Keeping the
  // search otherwise intact preserves other params and the route-mirror closure.
  const urlParams = new URLSearchParams(location.search);
  const urlHadWid = urlParams.has("wid");
  if (urlHadWid) {
    urlParams.delete("wid");
    const search = urlParams.toString();
    history.replaceState(null, "", location.pathname + (search ? `?${search}` : ""));
  }
  const renderer: DomRenderer = { byId };
  const transport = new Transport({
    url: `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}${base}/ws?wid=${wid}`,
    renderer,
    // The platform environment (viewport + current route) is the FIRST message:
    // the server session seeds its router from the ROUTE field before mount, so a
    // deep-linked URL renders the right destination (spec DSL.md §4.5).
    onOpen: (t) => {
      const { innerWidth: w, innerHeight: h } = window;
      log.info("route", `environment: viewport ${w}x${h}, route "${location.pathname}"`);
      t.send(encodeEnvironment(w, h, location.pathname));
      // Re-report every fitted slot's CURRENT fit now the socket is open — a
      // fit report emitted at boot (before the WS handshake) is dropped, so
      // without this a wide first load would never switch to the wide candidate.
      refreshFitSlots(renderer);
      // The SSR request never carries the wid, so it always rendered DEFAULT state. On a
      // same-tab reload (sessionStorage holds this window's wid) — or any load whose URL
      // carried a stale wid the SSR used — request a full snapshot to restore this
      // window's persisted state. A fresh window needs no snapshot: its defaults match
      // the fresh session's defaults.
      if (isReload || urlHadWid) {
        log.debug("route", "reload — requesting RESYNC for this window's persisted state");
        t.send(encodeResync());
      }
    },
  });
  transport.start();

  // Media events from app-driven AUDIO/VIDEO nodes (spec/EVENTS.md Media) ride
  // the same WebSocket as every raw input.
  renderer.onMediaEvent = (batch) => {
    if (transport.open) {
      transport.send(batch);
    }
  };
  // Fit changes from SIZE_THAT_FITS slots (spec/PRIMITIVES.md §SizeThatFits):
  // the slotted candidate index reported only on transitions.
  renderer.onFitEvent = (batch) => {
    if (transport.open) {
      transport.send(batch);
    }
  };
  // Wire app-driven media nodes hydrated from the SSR HTML (they carry the
  // `data-pathland-media` marker) so playback state reports to the app.
  for (const el of document.querySelectorAll<HTMLElement>("[data-pathland-media]")) {
    setupMediaElement(el, renderer);
  }

  // Hydrate fitted slots from the SSR HTML (they carry `data-pathland-fit`): an
  // initial measure reports the first derived index once; subsequent reports
  // arrive only on band crossings. The slot's own ResizeObserver detects width
  // changes locally (spec/PRIMITIVES.md). A slot with `data-pathland-fit-cands`
  // is the SSR full-snapshot form (issue #141): ALL candidates are present and
  // CSS `@container` band rules already gate the visible one, so no JS toggle is
  // needed for the first paint — the observer still reports FIT_CHANGED so the
  // live tree can downgrade to a single selected child (the N→1 reconcile).
  for (const el of document.querySelectorAll<HTMLElement>("[data-pathland-fit]")) {
    hydrateFitElement(el, renderer);
  }

  // Enrich the environment after connect: a window resize re-emits the viewport
  // fields (the mechanism future platform fields ride too).
  window.addEventListener("resize", () => {
    if (transport.open) {
      log.debug("route", `viewport resize -> ${window.innerWidth}x${window.innerHeight}`);
      transport.send(encodeEnvironment(window.innerWidth, window.innerHeight, location.pathname));
    }
  });

  // URL mirroring (spec DSL.md §4.5): the server emits the app-relative route as ROUTE;
  // we push the app's real URL (mount prefix prepended) so the browser URL follows the
  // app — a reload of `/app2/home` reaches the `/app2` app. pushState never fires
  // popstate, so server-originated navigation can't loop back into NAVIGATE events.
  // The wid query param is preserved so a reload after navigation still reaches SSR.
  renderer.onRoute = (path) => {
    log.info("route", `server navigated -> pushState("${mount}${path}")`);
    history.pushState(null, "", `${mount}${path}?${urlParams.toString()}`);
  };

  // Renderer-provided navigation chrome (spec DSL.md §4.5): a PlatformDefault nav
  // slot at depth > 1 shows the renderer's own back button (the web has no native
  // navigation container); clicking it is a NAVIGATE back request — the app pops.
  renderer.onNavigateBack = () => {
    log.info("route", "default back button -> NAVIGATE(back)");
    if (transport.open) {
      transport.send(encodeNavigateBack());
    }
  };
  // Hydrate the default back button from the SSR HTML (it carries data-pathland-depth).
  updateNavBackButtons(renderer);

  // Browser back/forward: popstate has already moved the URL; report it to the
  // server as a NAVIGATE event so the app routes (and re-emits the destination).
  window.addEventListener("popstate", () => {
    log.info("route", `popstate -> NAVIGATE("${location.href}")`);
    if (transport.open) {
      transport.send(encodeNavigate(location.href));
    }
  });

  // Hover tracking for POINTER_MOVE enter/leave.
  const hovered = new WeakSet<Element>();

  // --- pointer: down / move (hover) / up (tap) ---
  document.addEventListener("pointerdown", (event) => {
    const node = eventNodeOf(event.target as Element, LISTEN_POINTER_DOWN);
    if (!transport.open || !node) {
      return;
    }
    const id = Number(node.getAttribute("data-pathland-id"));
    const secondary = event.button !== 0 ? FLAG_POINTER_SECONDARY : 0;
    transport.send(encodePointerDown(id, event.clientX, event.clientY, secondary));
  });

  // In-flight interaction (spec EVENTS.md): while a range slider is being
  // dragged, inbound VALUE deltas are suppressed (the thumb is
  // user-authoritative until release), so a server echo can't cause flicker.
  // Sliders that declared the EDITING listener bit also get EDITING_CHANGED
  // boundaries (drag start/end) — e.g. a seek bar that commits on release.
  let activeEditingNode: HTMLElement | null = null;
  const endSliderEditing = () => {
    if (activeEditingNode) {
      transport.send(encodeEditingChanged(Number(activeEditingNode.getAttribute("data-pathland-id")), false));
      activeEditingNode = null;
    }
  };
  document.addEventListener(
    "pointerdown",
    (event) => {
      const target = event.target as Element | null;
      const range = target?.closest<HTMLInputElement>("input[type=range]");
      if (range) {
        markRangeInFlight(range);
        const node = range.closest<HTMLElement>("[data-pathland-id]");
        if (node && listens(node, LISTEN_EDITING)) {
          activeEditingNode = node;
          transport.send(encodeEditingChanged(Number(node.getAttribute("data-pathland-id")), true));
        }
      }
    },
    true,
  );
  document.addEventListener("pointerup", () => {
    endSliderEditing();
    clearInFlightRange();
  });
  document.addEventListener("pointercancel", () => {
    endSliderEditing();
    clearInFlightRange();
  });
  document.addEventListener("blur", () => {
    endSliderEditing();
    clearInFlightRange();
  }, true);

  document.addEventListener("pointermove", (event) => {
    const target = event.target as Element;
    const node = eventNodeOf(target, LISTEN_POINTER_MOVE);
    if (!transport.open || !node) {
      return;
    }
    const id = Number(node.getAttribute("data-pathland-id"));
    if (!hovered.has(target)) {
      hovered.add(target);
      transport.send(encodePointerMove(id, event.clientX, event.clientY, FLAG_HOVER_ENTER));
    }
  });
  document.addEventListener("pointerout", (event) => {
    const target = event.target as Element;
    const node = eventNodeOf(target, LISTEN_POINTER_MOVE);
    if (hovered.has(target)) {
      hovered.delete(target);
      if (transport.open && node) {
        const id = Number(node.getAttribute("data-pathland-id"));
        transport.send(encodePointerMove(id, event.clientX, event.clientY, FLAG_HOVER_LEAVE));
      }
    }
  });

  document.addEventListener("click", (event) => {
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    // Tap: the nearest listening node (any element, not just <button>) — a tap
    // gesture on a non-button container resolves to the container that declared it.
    const node = eventNodeOf(target, LISTEN_POINTER_UP);
    if (node && transport.open) {
      const id = Number(node.getAttribute("data-pathland-id"));
      const secondary = (event as MouseEvent).button !== 0 ? FLAG_POINTER_SECONDARY : 0;
      transport.send(encodePointerUp(id, (event as MouseEvent).clientX, (event as MouseEvent).clientY, secondary));
      return;
    }
    const stepButton = target.closest<HTMLElement>(".pathland-stepper button[data-step]");
    if (stepButton && transport.open) {
      const stepper = stepButton.closest<HTMLElement>(".pathland-stepper[data-pathland-id]");
      if (stepper) {
        const id = Number(stepper.getAttribute("data-pathland-id"));
        const valueEl = stepper.querySelector("span");
        const rangeEl = stepper.querySelector<HTMLElement>(".pathland-stepper-range");
        const current = Number(valueEl ? valueEl.textContent : 0);
        const dir = Number(stepButton.getAttribute("data-step"));
        const min = Number(rangeEl?.getAttribute("data-min"));
        const max = Number(rangeEl?.getAttribute("data-max"));
        const step = Number(rangeEl?.getAttribute("data-step"));
        const next = Math.min(max, Math.max(min, current + dir * step));
        transport.send(encodeValueChanged(id, next));
      }
    }
  });

  // --- keyboard (reported to the focused node) ---
  document.addEventListener("keydown", (event) => {
    const node = nodeOf(document.activeElement);
    if (!transport.open || !listens(node, LISTEN_KEY_DOWN)) {
      return;
    }
    transport.send(
      encodeKeyDown(Number(node!.getAttribute("data-pathland-id")), keyCodeOf(event), modifiersOf(event), event.repeat),
    );
  });
  document.addEventListener("keyup", (event) => {
    const node = nodeOf(document.activeElement);
    if (!transport.open || !listens(node, LISTEN_KEY_UP)) {
      return;
    }
    transport.send(
      encodeKeyUp(Number(node!.getAttribute("data-pathland-id")), keyCodeOf(event), modifiersOf(event)),
    );
  });

  // --- focus / editing (text inputs + editors) ---
  function focusTarget(event: FocusEvent): HTMLElement | null {
    const input = event.target as Element | null;
    if (!input || (!input.matches("input[type=text],input[type=password],textarea"))) {
      return null;
    }
    return nodeOf(input);
  }
  document.addEventListener("focusin", (event) => {
    const node = focusTarget(event);
    if (!transport.open || !node) {
      return;
    }
    const id = Number(node.getAttribute("data-pathland-id"));
    if (listens(node, LISTEN_FOCUS)) {
      transport.send(encodeFocusChanged(id, true));
    }
    if (listens(node, LISTEN_EDITING)) {
      transport.send(encodeEditingChanged(id, true));
    }
  });
  document.addEventListener("focusout", (event) => {
    const node = focusTarget(event);
    if (!transport.open || !node) {
      return;
    }
    const id = Number(node.getAttribute("data-pathland-id"));
    if (listens(node, LISTEN_FOCUS)) {
      transport.send(encodeFocusChanged(id, false));
    }
    if (listens(node, LISTEN_EDITING)) {
      transport.send(encodeEditingChanged(id, false));
    }
  });

  // --- scroll / wheel (scroll containers) ---
  document.addEventListener("scroll", (event) => {
    const scroller = event.target as Element | null;
    const node = nodeOf(scroller);
    if (!transport.open || !listens(node, LISTEN_SCROLL)) {
      return;
    }
    const el = scroller instanceof Element ? scroller : document.documentElement;
    transport.send(
      encodeScroll(Number(node!.getAttribute("data-pathland-id")), el.scrollLeft, el.scrollTop),
    );
  }, true);
  document.addEventListener(
    "wheel",
    (event) => {
      const node = nodeOf(event.target as Element);
      if (!transport.open || !listens(node, LISTEN_WHEEL)) {
        return;
      }
      transport.send(encodeWheel(Number(node!.getAttribute("data-pathland-id")), event.deltaX, event.deltaY));
    },
    { passive: true },
  );

  // --- value-bearing controls (toggles/selects/color/date) ---
  document.addEventListener("change", (event) => {
    if (!transport.open) {
      return;
    }
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    const toggle = target.closest<HTMLElement>("label.pathland-toggle[data-pathland-id]");
    if (toggle) {
      const box = toggle.querySelector<HTMLInputElement>("input[type=checkbox]");
      transport.send(
        encodeValueChanged(Number(toggle.getAttribute("data-pathland-id")), box && box.checked ? 1 : 0),
      );
      return;
    }
    const select = target.closest<HTMLSelectElement>("select[data-pathland-id]");
    if (select) {
      transport.send(encodeValueChanged(Number(select.getAttribute("data-pathland-id")), Number(select.value)));
      return;
    }
    const color = target.closest<HTMLInputElement>("input[type=color][data-pathland-id]");
    if (color) {
      const rgb = parseInt(color.value.slice(1), 16);
      transport.send(encodeValueBits(Number(color.getAttribute("data-pathland-id")), 0xff000000 | rgb));
      return;
    }
    const date = target.closest<HTMLInputElement>(
      "input[type=date][data-pathland-id],input[type=time][data-pathland-id],input[type=datetime-local][data-pathland-id]",
    );
    if (date) {
      const id = Number(date.getAttribute("data-pathland-id"));
      if (date.value) {
        if (date.type === "time") {
          const [h, m] = date.value.split(":").map(Number);
          transport.send(encodeDateChanged(id, 0, ((h ?? 0) * 3600 + (m ?? 0) * 60) * 1000));
        } else if (date.type === "datetime-local") {
          const [ymd, t] = date.value.split("T");
          const [y, mo, d] = (ymd ?? "").split("-").map(Number);
          const [h, mi] = (t ?? "").split(":").map(Number);
          const days = Math.round(Date.UTC(y ?? 0, (mo ?? 1) - 1, d ?? 1) / 86400000);
          transport.send(encodeDateChanged(id, days, ((h ?? 0) * 3600 + (mi ?? 0) * 60) * 1000));
        } else {
          const [y, m, d] = date.value.split("-").map(Number);
          const days = Math.round(Date.UTC(y ?? 0, (m ?? 1) - 1, d ?? 1) / 86400000);
          transport.send(encodeDateChanged(id, days, 0));
        }
      }
    }
  });

  // Sliders report live while dragging; text fields/editors report live while typing.
  document.addEventListener("input", (event) => {
    if (!transport.open) {
      return;
    }
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    const slider = target.closest<HTMLInputElement>("input[type=range]");
    if (slider) {
      const label = slider.closest<HTMLElement>("label.pathland-slider[data-pathland-id]");
      if (label) {
        transport.send(encodeValueChanged(Number(label.getAttribute("data-pathland-id")), Number(slider.value)));
      }
      return;
    }
    const textarea = target.closest<HTMLTextAreaElement>("textarea[data-pathland-id]");
    if (textarea) {
      transport.send(encodeTextChanged(Number(textarea.getAttribute("data-pathland-id")), textarea.value));
      return;
    }
    const input = target.closest<HTMLInputElement>("input[type=text],input[type=password]");
    if (!input) {
      return;
    }
    const label = input.closest<HTMLElement>("label.pathland-textfield[data-pathland-id]");
    if (label) {
      transport.send(encodeTextChanged(Number(label.getAttribute("data-pathland-id")), input.value));
    }
  });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot);
} else {
  boot();
}

// Delta application: decode each opcode and apply it to the DOM via the
// retained `id → Node` registry. PARAMETER deltas mutate the hydrated element in
// place; TREE deltas build the element shell and insert/remove/move it; META
// deltas reset/environment.

import {
  CAT_META,
  CAT_PARAMETER,
  CAT_TREE,
  CMD_CREATE_NODE,
  CMD_DELETE_NODE,
  CMD_ENVIRONMENT,
  CMD_INSERT_CHILD,
  CMD_MOVE_CHILD,
  CMD_REMOVE_CHILD,
  CMD_RESET,
  CMD_SET_DATE,
  CMD_SET_DESIGN_TOKEN,
  CMD_SET_PROPERTY,
  CMD_SET_TEXT,
  COMPONENT_AUDIO,
  COMPONENT_COLOR,
  COMPONENT_DIVIDER,
  COMPONENT_GRID,
  COMPONENT_GRID_ROW,
  COMPONENT_HSTACK,
  COMPONENT_LAZY_HGRID,
  COMPONENT_LAZY_HSTACK,
  COMPONENT_LAZY_VGRID,
  COMPONENT_LAZY_VSTACK,
  COMPONENT_PICKER,
  COMPONENT_PROGRESS_VIEW,
  COMPONENT_SCROLLVIEW,
  COMPONENT_SHAPE,
  COMPONENT_SPACER,
  COMPONENT_TEXT,
  COMPONENT_VSTACK,
  COMPONENT_VIDEO,
  COMPONENT_ZSTACK,
  PROP_ALIGNMENT,
  PROP_BINDING_ID,
  PROP_AUDIO_SOURCE,
  PROP_COLOR,
  PROP_COLOR_VALUE,
  PROP_ENABLED,
  PROP_FONT_FAMILY,
  PROP_GRID_COLUMNS,
  PROP_GRID_ROWS,
  PROP_GRID_TRACKS,
  PROP_IMAGE_SOURCE,
  PROP_IS_INDETERMINATE,
  PROP_LABEL,
  PROP_ICON_NAME,
  PROP_MEDIA_POSITION,
  PROP_MEDIA_VOLUME,
  PROP_NAV_CHROME,
  PROP_NAV_DEPTH,
  PROP_PLAYBACK_STATE,
  PROP_PROGRESS,
  PROP_PROMPT,
  PROP_ROLE,
  PROP_ROUTE,
  PROP_SELECTED,
  PROP_SELECTION,
  PROP_TEXT,
  PROP_TEXT_STYLE,
  PROP_VALUE,
  PROP_VIDEO_SOURCE,
  VAL_DESIGN_TOKEN,
  VAL_ENUM,
  VAL_LIST,
  VAL_STRING,
  VAL_U8,
} from "./constants";
import type { Batch, Opcode } from "./plpl";
import { readList, readString } from "./plpl";
import { childrenContainer, createElement } from "./elements";
import { alignHCss, alignVCss, applyEnabled, applyProperty, applyTokenRefProperty } from "./classes";
import { createTokenSink, applyDesignToken, type DesignTokenSink } from "./tokens";import {
  encodeFittedChanged,
  encodeMediaEnded,
  encodeMediaPlayStateChanged,
  encodeMediaTimeUpdated,
  encodeMediaVolumeChanged,
} from "./events";
import {
  GENERIC_COMPONENTS,
  NATIVE_ROLE_COMPONENTS,
  ariaRole,
  textTag,
} from "./generated/role-spec";
import { argbToHex, argbToRgba, daysToIso, f32FromBits, millisToTime } from "./format";
import { isRangeInFlight } from "./inFlight";
import { applyTextStyle, copyTypography, textStyleByNode } from "./typography";
import { setIcon } from "./icons";

/** Component type per retained node, so PARAMETER/TREE application can special-case
 *  per component (a ZSTACK child's absolute positioning, a ProgressView's
 *  spinner/progress morph) without baking it into the DOM. */
const componentByNode = new WeakMap<Node, number>();

/** Flex stacks (main axis horizontal). */
const STACK_MAIN_HORIZONTAL = new Set([COMPONENT_HSTACK, COMPONENT_LAZY_HSTACK]);
/** Flex stacks (main axis vertical). */
const STACK_MAIN_VERTICAL = new Set([COMPONENT_VSTACK, COMPONENT_LAZY_VSTACK]);
/** Hug-to-content containers that propagate a FILL descendant up (LAYOUT.md). */
const PROPAGATING = new Set([
  COMPONENT_VSTACK,
  COMPONENT_HSTACK,
  COMPONENT_ZSTACK,
  COMPONENT_LAZY_VSTACK,
  COMPONENT_LAZY_HSTACK,
]);

/** Whether `el` is effectively FILL-sized on `horizontal` (LAYOUT.md §fill
 *  propagation, SwiftUI/Compose parity): FILL itself (`width/height:100%`), a
 *  layout-greedy primitive, or a Hug container whose subtree carries one. A
 *  Fixed px box bounds its subtree. `mainAxis` = whether the axis is the
 *  element's parent's main axis (governs SPACER/DIVIDER greediness). A
 *  component-less shell (a ZStack child wrapper) is transparent. */
function fillsAxis(el: Element, horizontal: boolean, mainAxis: boolean): boolean {
  const comp = componentByNode.get(el) ?? 0;
  if (comp === 0) {
    return Array.from(el.children).some(
      (c) => c instanceof HTMLElement && fillsAxis(c, horizontal, mainAxis),
    );
  }
  const style = (el as HTMLElement).style;
  const hint = horizontal ? style.width : style.height;
  if (hint === "100%") {
    return true;
  }
  if (hint !== "") {
    return false; // a Fixed px box bounds its subtree
  }
  const greedy =
    comp === COMPONENT_COLOR ||
    comp === COMPONENT_SCROLLVIEW ||
    (comp === COMPONENT_SPACER && mainAxis) ||
    (comp === COMPONENT_DIVIDER && !mainAxis);
  if (greedy) {
    return true;
  }
  if (!PROPAGATING.has(comp)) {
    return false;
  }
  const childMain = STACK_MAIN_HORIZONTAL.has(comp)
    ? horizontal
    : STACK_MAIN_VERTICAL.has(comp)
      ? !horizontal
      : false;
  return Array.from(el.children).some(
    (c) => c instanceof HTMLElement && fillsAxis(c, horizontal, childMain),
  );
}

/** Derived layout pass (LAYOUT.md): fill propagation (a Hug stack/ZStack with a
 *  FILL descendant becomes FILL on that axis), ZStack hug-to-largest-child
 *  sizing, cross-axis `align-self:stretch` for FILL children, and ZStack child
 *  positioning. Mirrors the Rust SSR renderer's whole-tree layout decisions;
 *  runs after every batch so a delta leaves the derived styles consistent. */
function applyLayout(r: DomRenderer): void {
  const els = Array.from(r.byId.values()).filter(
    (n): n is HTMLElement => n instanceof HTMLElement,
  );
  // Phase 1: container fill propagation + ZStack sizing + grid cell alignment.
  for (const el of els) {
    const comp = componentByNode.get(el) ?? 0;
    if (!PROPAGATING.has(comp) && !isGridComponent(comp)) {
      continue;
    }
    if (STACK_MAIN_HORIZONTAL.has(comp) || STACK_MAIN_VERTICAL.has(comp)) {
      const mainH = STACK_MAIN_HORIZONTAL.has(comp);
      if (el.style.width === "" && fillsAxis(el, true, mainH)) {
        el.style.width = "100%";
      }
      if (el.style.height === "" && fillsAxis(el, false, !mainH)) {
        el.style.height = "100%";
      }
    } else if (comp === COMPONENT_ZSTACK) {
      if (el.style.width === "") {
        el.style.width = fillsAxis(el, true, false) ? "100%" : "max-content";
      }
      if (el.style.height === "") {
        el.style.height = fillsAxis(el, false, false) ? "100%" : "max-content";
      }
      // Position each child shell per the ZSTACK ALIGNMENT (2D code, both axes).
      const hToken = el.style.justifyItems || "start";
      const vToken = el.style.alignItems || "start";
      for (const w of Array.from(el.children)) {
        if (!(w instanceof HTMLElement)) {
          continue;
        }
        w.style.justifySelf = fillsAxis(w, true, false) ? "stretch" : hToken;
        w.style.alignSelf = fillsAxis(w, false, false) ? "stretch" : vToken;
        // The child's Z_INDEX orders its shell (the grid item) among the
        // overlapping siblings — the shell is what participates in stacking,
        // not the child (a plain block inside it). EVERY shell gets an explicit
        // z-index (the child's, else 0) so overlapping grid items paint
        // deterministically in every browser (WebKit paints a non-fill grid
        // item below a full-area sibling when both are z-index:auto). Mirrors
        // the Rust SSR.
        const inner = w.firstElementChild;
        const innerZ = inner instanceof HTMLElement ? inner.style.zIndex : "";
        w.style.zIndex = innerZ || "0";
      }
    } else if (isGridComponent(comp)) {
      // Position each cell shell per the grid ALIGNMENT (2D code) on both axes
      // (spec §grid model): a FILL-sized / greedy cell stretches to fill its
      // track. Explicit rows (spec §GridRow): a GRID_ROW starts a new row; bare
      // cells auto-flow, advancing after the effective column count
      // (GRID_COLUMNS or the widest row) — short rows leave trailing columns
      // empty.
      const hToken = el.style.justifyItems || "start";
      const vToken = el.style.alignItems || "start";
      const children = Array.from(el.children).filter(
        (c): c is HTMLElement => c instanceof HTMLElement,
      );
      const explicitRows = children.some(
        (c) => componentByNode.get(c) === COMPONENT_GRID_ROW,
      );
      const parseCount = (s: string): number | null => {
        const m = /repeat\(\s*(\d+)/.exec(s);
        return m ? Number(m[1]) : null;
      };
      const setShell = (shell: HTMLElement, row: number, col: number): void => {
        if (explicitRows) {
          shell.style.gridRow = String(row + 1);
          shell.style.gridColumn = String(col + 1);
        }
        shell.style.justifySelf = fillsAxis(shell, true, false) ? "stretch" : hToken;
        shell.style.alignSelf = fillsAxis(shell, false, false) ? "stretch" : vToken;
        // The cell's Z_INDEX orders its shell (the grid item); see the ZSTACK note.
        const inner = shell.firstElementChild;
        shell.style.zIndex = inner instanceof HTMLElement ? inner.style.zIndex : "";
      };
      if (!explicitRows) {
        for (const w of children) {
          setShell(w, 0, 0);
        }
      } else {
        let cols = parseCount(el.style.gridTemplateColumns);
        let width = cols ?? 0;
        let run = 0;
        for (const c of children) {
          if (componentByNode.get(c) === COMPONENT_GRID_ROW) {
            width = Math.max(width, c.children.length);
            run = 0;
          } else {
            run += 1;
            width = Math.max(width, run);
          }
        }
        width = Math.max(width, 1);
        if (cols === null) {
          el.style.gridTemplateColumns = `repeat(${width},minmax(0,1fr))`;
          cols = width;
        }
        const columns = cols ?? width;
        let row = 0;
        let col = 0;
        for (const c of children) {
          if (componentByNode.get(c) === COMPONENT_GRID_ROW) {
            if (col > 0) {
              row += 1;
            }
            col = 0;
            for (const shell of Array.from(c.children).filter(
              (s): s is HTMLElement => s instanceof HTMLElement,
            )) {
              setShell(shell, row, col);
              col += 1;
            }
            row += 1;
            col = 0;
          } else {
            if (col >= columns) {
              row += 1;
              col = 0;
            }
            setShell(c, row, col);
            col += 1;
          }
        }
      }
    }
  }
  // Phase 2: cross-axis FILL children in a stack stretch via align-self.
  for (const el of els) {
    const parent = el.parentElement;
    if (!parent) {
      continue;
    }
    const parentComp = componentByNode.get(parent) ?? 0;
    const mainH = STACK_MAIN_HORIZONTAL.has(parentComp);
    if (!STACK_MAIN_HORIZONTAL.has(parentComp) && !STACK_MAIN_VERTICAL.has(parentComp)) {
      continue;
    }
    if (fillsAxis(el, !mainH, false)) {
      el.style.alignSelf = "stretch";
    }
  }
}

/** The last `ROLE` code applied per element (morphing needs both role and text
 *  style to resolve the effective tag). */
const roleByNode = new WeakMap<HTMLElement, number>();

/** The retained `node id → DOM Node` registry the renderer works against. */
export interface DomRenderer {
  byId: Map<number, Node>;
  /**
   * Optional hook invoked when a slot's `ROUTE` property changes — the host wires it
   * to `history.pushState` so the browser URL mirrors the app's navigation (spec
   * DSL.md §4.5). Not called on hydrate (the URL is already correct).
   */
  onRoute?: (path: string) => void;
  /**
   * Optional hook invoked when the renderer's default back button (a
   * `PlatformDefault` nav slot at depth > 1) is clicked — the host wires it to a
   * `NAVIGATE` event with no URL, so the app pops its own back-stack (spec DSL.md
   * §4.5). Null/absent when the slot is `Custom` chrome or at depth 1.
   */
  onNavigateBack?: () => void;
  /** Optional design-token sink (defaults to document-root CSS variables). */
  tokenSink?: DesignTokenSink;
  /**
   * Optional media-event sink: the host wires it to `transport.send` so a bound
   * `AUDIO`/`VIDEO` node can report play/pause/time/ended/volume (host → guest).
   */
  onMediaEvent?: (batch: Uint8Array) => void;
  /**
   * Optional fit-event sink: the host wires it to `transport.send` so a
   * `SIZE_THAT_FITS` slot can report its derived fit index (`FIT_CHANGED`).
   */
  onFitEvent?: (batch: Uint8Array) => void;
}

/** Apply every opcode in a batch to the DOM (TREE structure + PARAMETER/META deltas). */
export function applyBatch(batch: Batch, renderer: DomRenderer): void {
  // SSR snapshot fit slots (`data-pathland-fit-cands`) touched by a structural
  // removal in this batch. The gate is torn down AFTER the whole batch, gated on
  // the slot's FINAL state (issue #141): a removal that does NOT reduce the slot
  // to a single live candidate (e.g. a band-crossing fit swap dropping a child
  // inside a candidate) must leave the gate intact — unwrapping it eagerly would
  // expose every candidate (the "all branches rendered" bug).
  const touchedFitGates = new Set<HTMLElement>();
  for (let i = 0; i < batch.opcodes.length; i++) {
    const op = batch.opcodes[i]!;
    try {
      switch (op.category) {
        case CAT_TREE:
          applyTree(op, renderer, touchedFitGates);
          break;
        case CAT_PARAMETER:
          applyStyle(op, batch.strings, renderer);
          break;
        case CAT_META:
          applyMeta(op, renderer);
          break;
        default:
          break;
      }
    } catch (err) {
      // The batch is a renderer-consuming instruction stream; an empty catch
      // would hide a structural bug. Log the exact op for remote diagnosis,
      // then rethrow (the host's handleMessage surfaces it).
      const el = renderer.byId.get(op.a);
      const where = el instanceof Element
        ? `${el.tagName.toLowerCase()}#${el.getAttribute("data-pathland-id")}.${el.className}`
        : String(el);
      console.error(
        `[pathland] applyBatch failed at op ${i}/${batch.opcodes.length} ` +
        `cat=${op.category} cmd=${op.command} a=${op.a} b=${op.b} c=${op.c} target=${where}`, err);
      throw err;
    }
  }
  for (const slot of touchedFitGates) {
    reconcileFitGate(slot);
  }
  // Derived layout (fill propagation, ZStack sizing/positioning, cross-axis
  // align-self) — mirrors the Rust SSR renderer's whole-tree decisions.
  applyLayout(renderer);
}

function applyMeta(op: Opcode, r: DomRenderer): void {
  switch (op.command) {
    case CMD_RESET: {
      for (const el of Array.from(r.byId.values())) {
        if (el.parentNode) {
          el.parentNode.removeChild(el);
        }
      }
      r.byId.clear();
      break;
    }
    case CMD_ENVIRONMENT:
    default:
      break;
  }
}

/** The node actually inserted into a parent's container: ZStack children are
 *  wrapped in a `grid-area:1/1` cell shell, grid cells (a GRID's bare children
 *  or a GRID_ROW's children) in an auto-placed cell shell (the layout pass sets
 *  their `justify-self`/`align-self` and explicit `grid-row`/`grid-column` from
 *  the container's structure/ALIGNMENT — mirrors the Rust SSR renderer), a
 *  GRID_ROW itself inserts directly (it is the row container, not a cell);
 *  everything else inserts directly. */
function placedChild(parent: Node, child: Node): Node {
  if (child instanceof HTMLElement) {
    const parentComp = componentByNode.get(parent);
    if (parentComp === COMPONENT_ZSTACK) {
      const wrapper = document.createElement("div");
      wrapper.style.gridArea = "1/1";
      wrapper.appendChild(child);
      return wrapper;
    }
    if (isGridComponent(parentComp) || parentComp === COMPONENT_GRID_ROW) {
      if (componentByNode.get(child) === COMPONENT_GRID_ROW) {
        return child; // a row container is a grid child, not a cell
      }
      const wrapper = document.createElement("div");
      wrapper.appendChild(child);
      return wrapper;
    }
  }
  return child;
}

/** Materialize a PICKER's child TEXT node as a native `<option>` (the Rust SSR
 *  renderer emits `<option data-pathland-id="{child}" value="{index}">` per
 *  child). The option keeps the child's id so its PARAMETER deltas resolve to it. */
function pickerOption(child: HTMLElement): HTMLElement {
  const opt = document.createElement("option");
  opt.textContent = child.textContent ?? "";
  const id = child.getAttribute("data-pathland-id");
  if (id) {
    opt.setAttribute("data-pathland-id", id);
  }
  return opt;
}

/** Keep a PICKER's option `value` attributes aligned with their index (the SSR
 *  renderer's `<option value="{i}">` scheme). */
function renumberPickerOptions(container: Node): void {
  if (!(container instanceof HTMLSelectElement)) {
    return;
  }
  Array.from(container.options).forEach((o, i) => {
    o.value = String(i);
  });
}

function applyTree(op: Opcode, r: DomRenderer, touchedFitGates: Set<HTMLElement>): void {
  // N→1 fit-slot reconcile (issue #141): the server's SSR snapshot carried EVERY
  // candidate behind CSS `@container` gated wrappers (`data-pathland-fit-cands`).
  // The downgrade to a single selected child is signalled by REMOVING a candidate
  // (a `REMOVE_CHILD`/`DELETE_NODE` on the slot). Record the touched slot and
  // reconcile it AFTER the batch (`reconcileFitGate`), once the REMOVE/DELETE
  // deltas have applied: only a slot that actually ended up with a single live
  // candidate is the downgrade — a removal that merely drops a child inside a
  // candidate (a band-crossing fit swap) must leave the gate intact. An
  // `INSERT_CHILD`/`CREATE_NODE` is never the downgrade: a `META::RESYNC` replays
  // the whole tree and the SSR gate must SURVIVE it (the CSS band keeps showing the
  // width-correct candidate).
  if (op.command === CMD_REMOVE_CHILD || op.command === CMD_DELETE_NODE) {
    const slot = nearestGatedFitSlot(op, r);
    if (slot) {
      touchedFitGates.add(slot);
    }
  }
  switch (op.command) {
    case CMD_CREATE_NODE: {
      // Hydration-aware: an id already present in the registry is the SSR-hydrated
      // element — reuse it (a resync/full snapshot replays CREATE for every node
      // without clobbering the visible DOM). Only create a fresh shell when absent.
      let el = r.byId.get(op.a);
      if (!el) {
        el = createElement(op.b);
        if (el.nodeType === Node.ELEMENT_NODE) {
          (el as HTMLElement).setAttribute("data-pathland-id", String(op.a));
        }
        r.byId.set(op.a, el);
      }
      if (el.nodeType === Node.ELEMENT_NODE) {
        componentByNode.set(el, op.b);
      }
      break;
    }
    case CMD_DELETE_NODE: {
      const el = r.byId.get(op.a);
      if (el) {
        const host = el as HTMLElement;
        // `DELETE_NODE` covers the whole subtree: every descendant's registry
        // entry must die too, or a later op could reuse a still-registered
        // (detached) element and double-parent it (HierarchyRequestError).
        purgeSubtreeRegistry(host, r);
        if (host.parentNode) {
          host.parentNode.removeChild(host);
        }
      }
      r.byId.delete(op.a);
      break;
    }
    case CMD_INSERT_CHILD: {
      const child = r.byId.get(op.b);
      const parentNode = r.byId.get(op.a);
      if (!child || !parentNode) {
        break;
      }
      let parent: Node = parentNode;
      // A media node gaining custom control children morphs its bare media
      // element into a `.pathland-media` wrapper (the Rust SSR emits the same
      // structure); the children then attach to the wrapper.
      const comp = componentByNode.get(parentNode);
      if ((comp === COMPONENT_AUDIO || comp === COMPONENT_VIDEO)
          && parentNode instanceof HTMLElement && parentNode.matches("audio,video")) {
        parent = mediaToWrapper(parentNode, r);
      }
      const container = childrenContainer(parent);
      // Hydration/idempotent-replay guard: skip when the child is already there
      // (the SSR DOM already holds the initial tree; a resync replays it), or
      // when a duplicate of the node already exists by id (drift protection —
      // never render a second copy the app did not emit).
      if (container && !container.contains(child)
          && !(child instanceof Element && container instanceof Element
            && container.querySelector(`[data-pathland-id="${op.b}"]`))) {
        let placed = placedChild(parent, child);
        if (comp === COMPONENT_PICKER && child instanceof HTMLElement) {
          // Picker children are option labels → materialize native `<option>`s.
          placed = pickerOption(child);
          r.byId.set(op.b, placed);
          componentByNode.set(placed, COMPONENT_TEXT);
        }
        insertAt(container, placed, op.c);
        if (comp === COMPONENT_PICKER) {
          renumberPickerOptions(container);
        }
        maybeAnimateInsert(parent, placed);
      }
      break;
    }
    case CMD_REMOVE_CHILD: {
      const child = r.byId.get(op.b);
      if (child && child.parentNode) {
        child.parentNode.removeChild(child);
      }
      break;
    }
    case CMD_MOVE_CHILD: {
      const child = r.byId.get(op.b);
      if (!child) {
        break;
      }
      const parent = r.byId.get(op.a);
      if (parent) {
        const container = childrenContainer(parent);
        if (container) {
          // Detach the child (and its now-empty ZStack wrapper, if any) so the
          // wrapper-count stays in sync with the Rust SSR structure.
          const oldParent = child.parentNode;
          child.parentNode?.removeChild(child);
          if (
            oldParent instanceof HTMLElement &&
            oldParent !== container &&
            oldParent.childElementCount === 0 &&
            oldParent.style.position === "absolute"
          ) {
            oldParent.remove();
          }
          let placed = placedChild(parent, child);
          if (componentByNode.get(parent) === COMPONENT_PICKER && child instanceof HTMLElement) {
            placed = pickerOption(child);
            r.byId.set(op.b, placed);
            componentByNode.set(placed, COMPONENT_TEXT);
          }
          insertAt(container, placed, op.c);
          if (componentByNode.get(parent) === COMPONENT_PICKER) {
            renumberPickerOptions(container);
          }
        }
      }
      break;
    }
    default:
      break;
  }
}

function insertAt(container: Node, child: Node, index: number): void {
  // Inserting a node into itself or its own subtree yields an incorrect node
  // tree — the child is effectively already positioned; skip (never throw).
  if (child === container || container.contains(child)) {
    return;
  }
  // The protocol's INSERT/MOVE index counts ELEMENT children. Debug-comment
  // nodes (`<!-- #id … -->`, `pathland.debug-html=true`) are sibling children
  // in the SSR-hydrated DOM, so counting them in `visible` shifts every index
  // and e.g. would insert a trailing sidebar BEFORE the main area. Count
  // elements only; the injected nav-back button is excluded by class.
  const visible = Array.from(container.childNodes).filter(
    (n) =>
      n.nodeType === Node.ELEMENT_NODE &&
      !(n instanceof HTMLElement && n.classList.contains(NAV_BACK_CLASS)),
  );
  const target = visible[index];
  detachIfWrongParent(container, child);
  if (target) {
    if (target === child || target.contains(child)) {
      // Would yield an incorrect node tree (inserting a node before itself or a
      // descendant) — the child is already positioned; nothing to do.
      return;
    }
    container.insertBefore(child, target);
  } else {
    container.appendChild(child);
  }
}

// --- renderer-provided navigation chrome (spec DSL.md §4.5) ---
// A `PlatformDefault` nav slot at depth > 1 gets a default back button drawn by
// the DOM renderer (the web has no native navigation container). The button is
// a tracked child of the slot that the reconcile ignores (see `insertAt`), so
// TREE deltas never displace it. `Custom` chrome slots never get one.

/** The injected default back button's class (excluded from child indexing). */
export const NAV_BACK_CLASS = "pathland-nav-back";

/** Whether an element is a nav slot (carries a `data-pathland-route`). */
function isNavSlot(el: HTMLElement): boolean {
  return el.hasAttribute("data-pathland-route");
}

/** The slot's chrome mode: `true` when the developer owns all nav UI. */
function isCustomChrome(el: HTMLElement): boolean {
  return el.getAttribute("data-pathland-nav-chrome") === "custom";
}

/** The slot's current depth (defaults to 1 = root destination). */
function slotDepth(el: HTMLElement): number {
  return Math.max(1, Number(el.getAttribute("data-pathland-depth") ?? "1") || 1);
}

/** The injected back button inside a slot, if present. */
function injectedBackButton(el: HTMLElement): HTMLButtonElement | null {
  return el.querySelector<HTMLButtonElement>(`.${NAV_BACK_CLASS}`);
}

/**
 * Reconcile the renderer's default back button for a nav slot: shown for a
 * `PlatformDefault` slot at depth > 1, removed for `Custom` chrome or depth 1.
 * Called from `SET_PROPERTY` (depth/chrome changes) and once at hydrate.
 */
export function updateNavBackButton(el: HTMLElement, r: DomRenderer): void {
  if (!isNavSlot(el) || isCustomChrome(el) || slotDepth(el) <= 1) {
    injectedBackButton(el)?.remove();
    return;
  }
  let back = injectedBackButton(el);
  if (!back) {
    back = document.createElement("button");
    back.type = "button";
    back.className = NAV_BACK_CLASS;
    back.setAttribute("aria-label", "Back");
    back.textContent = "‹ Back";
    back.addEventListener("click", () => r.onNavigateBack?.());
    el.insertBefore(back, el.firstChild); // above the destination
  }
}

/** Reconcile the default back button for every nav slot in the tree (hydrate). */
export function updateNavBackButtons(r: DomRenderer): void {
  for (const node of r.byId.values()) {
    if (node instanceof HTMLElement && isNavSlot(node)) {
      updateNavBackButton(node, r);
    }
  }
}

// --- swap transitions (spec DSL.md §4.5 / MODIFIERS.md TRANSITION) ---
// When a child is inserted into a slot carrying a `data-pathland-transition` hint,
// the DOM client animates the new subtree in (fade/slide/scale). This is a pure
// renderer-side animation of its own output cache — never app state.

const TRANSITION_KEYFRAMES: Record<string, string> = {
  platform: "@keyframes pl-platform { from { opacity: 0; } to { opacity: 1; } }",
  fade: "@keyframes pl-fade { from { opacity: 0; } to { opacity: 1; } }",
  slide:
    "@keyframes pl-slide { from { opacity: 0; transform: translateX(16px); } to { opacity: 1; transform: none; } }",
  scale:
    "@keyframes pl-scale { from { opacity: 0; transform: scale(0.96); } to { opacity: 1; transform: none; } }",
};

let transitionsInjected = false;

function ensureTransitionStyles(): void {
  if (transitionsInjected || typeof document === "undefined") {
    return;
  }
  transitionsInjected = true;
  const style = document.createElement("style");
  style.setAttribute("data-pathland-transitions", "");
  style.textContent = Object.values(TRANSITION_KEYFRAMES).join("\n");
  document.head.appendChild(style);
}

function maybeAnimateInsert(parent: Node, child: Node): void {
  if (!(parent instanceof HTMLElement) || !(child instanceof HTMLElement)) {
    return;
  }
  const name = parent.getAttribute("data-pathland-transition");
  if (!name) {
    return;
  }
  ensureTransitionStyles();
  const key = TRANSITION_KEYFRAMES[name] ? name : "platform";
  child.style.animation = `pl-${key} 180ms ease-out`;
  child.addEventListener("animationend", () => {
    child.style.animation = "";
  }, { once: true });
}

/** Resolve an element's role shell kind: from the component when known (fresh
 *  nodes), else from its tag (SSR-hydrated nodes have no component). */
function shellKind(el: HTMLElement): "generic" | "native" | "other" {
  const comp = componentByNode.get(el);
  if (comp !== undefined) {
    if (GENERIC_COMPONENTS.includes(comp)) {
      return "generic";
    }
    if (NATIVE_ROLE_COMPONENTS.includes(comp)) {
      return "native";
    }
    return "other";
  }
  const t = el.tagName.toLowerCase();
  if (t === "div" || t === "span") {
    return el.classList.contains("pathland-menu") || el.classList.contains("pathland-stepper")
      ? "other"
      : "generic";
  }
  if (
    t === "button" ||
    t === "input" ||
    t === "label" ||
    t === "select" ||
    t === "textarea" ||
    t === "progress" ||
    t === "img"
  ) {
    return "native";
  }
  return "other";
}

/** Replace an element with one of a different tag (a semantic role retag),
 *  preserving attributes, children, and the registry entry. */
function morphRole(el: HTMLElement, tag: string, r: DomRenderer): HTMLElement {
  const fresh = document.createElement(tag);
  for (const attr of Array.from(el.attributes)) {
    fresh.setAttribute(attr.name, attr.value);
  }
  while (el.firstChild) {
    fresh.appendChild(el.firstChild);
  }
  if (el.parentNode) {
    el.parentNode.replaceChild(fresh, el);
  }
  const id = Number(el.getAttribute("data-pathland-id"));
  if (id) {
    r.byId.set(id, fresh);
  }
  const comp = componentByNode.get(el);
  if (comp !== undefined) {
    componentByNode.set(fresh, comp);
  }
  const role = roleByNode.get(el);
  if (role !== undefined) {
    roleByNode.set(fresh, role);
  }
  copyTypography(el, fresh);
  return fresh;
}

/** Resolve and apply the semantic tag + ARIA role for an element from its
 *  current `ROLE` / `TEXT_STYLE` state (a heading `TEXT_STYLE` always wins).
 *  Retags a generic shell in place when the effective tag differs. */
function applySemantic(el: HTMLElement, r: DomRenderer): void {
  const kind = shellKind(el);
  const role = roleByNode.get(el) ?? 0;
  const style = textStyleByNode.get(el);
  const tag = textTag(kind, role, style ?? null);
  let current = el;
  if (tag && current.tagName.toLowerCase() !== tag) {
    current = morphRole(current, tag, r);
  }
  const aria = ariaRole(kind, role);
  if (aria) {
    current.setAttribute("role", aria);
  } else {
    current.removeAttribute("role");
  }
}

function applyStyle(op: Opcode, strings: Uint8Array, r: DomRenderer): void {
  if (op.command === CMD_SET_DESIGN_TOKEN) {
    applyDesignToken(op, strings, r.tokenSink ?? createTokenSink());
    return;
  }
  const node = r.byId.get(op.a);
  if (!node || node.nodeType !== Node.ELEMENT_NODE) {
    return;
  }
  const el = node as HTMLElement;
  switch (op.command) {
    case CMD_SET_TEXT:
      setNodeText(el, readString(strings, op.b));
      break;
    case CMD_SET_DATE: {
      const input = el.matches("input[type=date],input[type=time],input[type=datetime-local]")
        ? (el as HTMLInputElement)
        : el.querySelector<HTMLInputElement>("input[type=date],input[type=time],input[type=datetime-local]");
      if (input) {
        if (input.type === "time") {
          input.value = millisToTime(op.c);
        } else if (input.type === "datetime-local") {
          const date = daysToIso(op.b);
          const time = millisToTime(op.c);
          input.value = date ? `${date}T${time}` : time;
        } else {
          input.value = daysToIso(op.b);
        }
      }
      break;
    }
    case CMD_SET_PROPERTY: {
      const propId = op.b & 0xffff;
      const valueType = (op.b >>> 16) & 0xff;
      if (valueType === VAL_STRING) {
        const text = readString(strings, op.c);
        if (propId === PROP_ROUTE) {
          el.setAttribute("data-pathland-route", text);
          r.onRoute?.(text); // host mirrors the URL (history.pushState)
        } else {
          applyStringProperty(el, propId, text);
          if (propId === PROP_AUDIO_SOURCE || propId === PROP_VIDEO_SOURCE) {
            // Wire a media node's element + listeners, finalize native controls
            // (a control-less media node renders native controls), and resume
            // playback if the app was playing (a src change pauses the element).
            ensureMediaElement(el, propId);
            applyStringProperty(el, propId, text);
            setupMediaElement(el, r);
            finalizeNativeMedia(el);
            resumeIfPlaying(el);
          }
        }
      } else if (valueType === VAL_DESIGN_TOKEN) {
        applyTokenRefProperty(el, propId, readString(strings, op.c));
      } else if (valueType === VAL_LIST) {
        applyFitQuery(el, r, readList(strings, op.c));
      } else if (componentByNode.get(el) === COMPONENT_PROGRESS_VIEW
              && (propId === PROP_IS_INDETERMINATE || propId === PROP_PROGRESS)) {
        applyProgress(el, r, propId, valueType, op.c);
      } else if (propId === PROP_ROLE) {
        // Semantic role → native element where one exists (generated role-spec):
        // a generic shell is retagged to its semantic element; the ARIA `role`
        // attribute is set only when the element does not already convey it.
        roleByNode.set(el, Math.round(f32FromBits(op.c)) & 0xff);
        applySemantic(el, r);
      } else if (propId === PROP_TEXT_STYLE) {
        // A heading `TEXT_STYLE` (LargeTitle…Headline) makes a TEXT a heading
        // (`<h1>`–`<h5>`) — always, even without `ROLE_HEADER`; raw font
        // modifiers never imply a heading. Absence is "no style" (the enum has
        // no NONE — LARGE_TITLE is code 0, a real heading style). The style also
        // sets its default size/weight, unless an explicit FONT_SIZE/FONT_WEIGHT
        // override was applied (raw modifiers layer on top).
        applyTextStyle(el, Math.round(f32FromBits(op.c)) & 0xff);
        applySemantic(el, r);
      } else if (propId === PROP_NAV_DEPTH) {
        // Back-stack depth on a nav slot → the renderer's default back button.
        el.setAttribute("data-pathland-depth", String(op.c));
        updateNavBackButton(el, r);
      } else if (propId === PROP_NAV_CHROME) {
        // Chrome mode: PlatformDefault=0 / Custom=1 (F32 enum code).
        const custom = Math.round(f32FromBits(op.c)) === 1;
        if (custom) {
          el.setAttribute("data-pathland-nav-chrome", "custom");
        } else {
          el.removeAttribute("data-pathland-nav-chrome");
        }
        updateNavBackButton(el, r);
      } else if (propId === PROP_PLAYBACK_STATE || propId === PROP_MEDIA_POSITION
              || propId === PROP_MEDIA_VOLUME) {
        applyMediaProperty(el, r, propId, valueType, op.c);
      } else {
        applyNumericProperty(el, propId, valueType, op.c);
      }
      break;
    }
    default:
      break;
  }
}

/** Set a node's text, honoring text fields/editors and label spans (SSR structure). */
export function setNodeText(el: HTMLElement, text: string): void {
  const input = el.querySelector("input[type=text],input[type=password]");
  if (input instanceof HTMLInputElement) {
    input.value = text;
    return;
  }
  const textarea = el.querySelector("textarea");
  if (textarea instanceof HTMLTextAreaElement) {
    textarea.value = text;
    return;
  }
  const trigger = el.querySelector(".pathland-menu-trigger");
  if (trigger) {
    trigger.textContent = text;
    return;
  }
  const span = el.querySelector(".pathland-text");
  if (span) {
    span.textContent = text;
    return;
  }
  // Only a leaf (no element children) falls through to textContent: re-applying a
  // composite's LABEL/TEXT property must never wipe its children (SSR renders no
  // label on composites — a composite's children are its body).
  if (el.childElementCount === 0) {
    el.textContent = text;
  }
}

/** Set an icon's accessibility: a `LABEL` makes it presentable
 *  (`role="img"` + `aria-label`); without one it is decorative (`aria-hidden`). */
function syncIconAria(el: Element, label?: string): void {
  if (label) {
    el.setAttribute("role", "img");
    el.setAttribute("aria-label", label);
    el.removeAttribute("aria-hidden");
    el.removeAttribute("focusable");
  } else {
    el.removeAttribute("role");
    el.removeAttribute("aria-label");
    el.setAttribute("aria-hidden", "true");
    el.setAttribute("focusable", "false");
  }
}

function applyStringProperty(el: HTMLElement, propId: number, text: string): void {
  switch (propId) {
    case PROP_TEXT:
    case PROP_LABEL: {
      // On a media element the accessibility label is the `alt` text (mirrors
      // the Rust SSR renderer); on a semantic icon it makes the svg presentable;
      // elsewhere it's the caption/label span.
      const icon = el.matches("svg.pathland-icon")
        ? el
        : el.querySelector("svg.pathland-icon");
      const media = el.matches("img,audio,video") ? el : null;
      if (media) {
        media.setAttribute("alt", text);
      } else if (icon) {
        syncIconAria(icon, text);
      } else {
        const span = el.querySelector(".pathland-label");
        if (span) {
          span.textContent = text;
        } else {
          setNodeText(el, text);
        }
      }
      break;
    }
    case PROP_ICON_NAME: {
      // A semantic icon: swap the filled inner markup for the canonical name.
      // The glyph comes from an embedded sibling / the memo cache / a lazy
      // fetch of the renderer-owned `/_pathland/icons/<name>.svg` (icons.ts).
      const svg = el.matches("svg.pathland-icon")
        ? el
        : el.querySelector("svg.pathland-icon");
      if (svg) {
        setIcon(svg, text);
      }
      break;
    }
    case PROP_PROMPT: {
      const input = el.querySelector("input[type=text]");
      if (input instanceof HTMLInputElement) {
        input.placeholder = text;
      }
      break;
    }
    case PROP_IMAGE_SOURCE: {
      const img = el.matches("img") ? el : el.querySelector("img");
      if (img instanceof HTMLImageElement) {
        img.src = text;
      }
      break;
    }
    case PROP_AUDIO_SOURCE: {
      const audio = el.matches("audio") ? el : el.querySelector("audio");
      if (audio instanceof HTMLAudioElement) {
        audio.src = text;
      }
      break;
    }
    case PROP_VIDEO_SOURCE: {
      const video = el.matches("video") ? el : el.querySelector("video");
      if (video instanceof HTMLVideoElement) {
        video.src = text;
      }
      break;
    }
    case PROP_FONT_FAMILY: {
      el.style.fontFamily = text;
      break;
    }
    case PROP_GRID_TRACKS: {
      // A grid's per-track spec (spec §grid model): `flex`/`fixed:<pts>`/
      // `adaptive:<pts>` comma-separated → the CSS track template; takes
      // precedence over the count (the DSL emits one or the other).
      const comp = componentByNode.get(el);
      const isH = comp === COMPONENT_LAZY_HGRID;
      const tracks = text.split(",").map((t) => t.trim());
      const css = tracks
        .map((t) => {
          if (t.startsWith("fixed:")) return `${t.slice("fixed:".length)}px`;
          if (t.startsWith("adaptive:")) return `minmax(${t.slice("adaptive:".length)}px,1fr)`;
          return "1fr";
        })
        .join(" ");
      if (isH) {
        el.style.gridTemplateRows = css;
      } else {
        el.style.gridTemplateColumns = css;
      }
      break;
    }
    default:
      break;
  }
}

function applyNumericProperty(el: HTMLElement, propId: number, valueType: number, bits: number): void {
  switch (propId) {
    case PROP_SELECTED: {
      const input = el.querySelector<HTMLInputElement>("input[type=checkbox]");
      if (input) {
        const on = (valueType === 0x01 ? bits & 0xff : bits) !== 0;
        input.checked = on;
        // Button-style toggles are rendered with `role=checkbox` + `aria-pressed`
        // (the Rust SSR renderer's TOGGLE_STYLE=Button); switch/checkbox styles
        // carry only the native `checked` state.
        if (input.getAttribute("role") === "checkbox") {
          input.setAttribute("aria-pressed", on ? "true" : "false");
        }
      }
      break;
    }
    case PROP_VALUE: {
      const range = el.querySelector<HTMLInputElement>("input[type=range]");
      // In-flight interaction (spec EVENTS.md): while the user is dragging the
      // slider, its thumb is user-authoritative — a server echo of VALUE must
      // not fight the pointer (flicker).
      if (range && !isRangeInFlight(range)) {
        range.value = String(f32FromBits(bits));
      }
      const stepText = el.querySelector(".pathland-stepper span");
      if (stepText) {
        stepText.textContent = String(Math.round(f32FromBits(bits) * 100) / 100);
      }
      const gauge = el.matches(".pathland-gauge")
        ? el
        : el.querySelector<HTMLElement>(".pathland-gauge");
      if (gauge) {
        const max = Number(gauge.dataset.max ?? 1);
        const min = Number(gauge.dataset.min ?? 0);
        const span = max - min;
        const pct = span <= 0 ? 0 : ((f32FromBits(bits) - min) / span) * 100;
        const bar = gauge.firstElementChild;
        if (bar instanceof HTMLElement) {
          bar.style.width = pct + "%";
        }
      }
      break;
    }
    case PROP_SELECTION: {
      const select = el.matches("select")
        ? (el as HTMLSelectElement)
        : el.querySelector<HTMLSelectElement>("select");
      if (select) {
        // Index-based, matching the SSR `<option value="{index}">` scheme.
        select.selectedIndex = bits;
      }
      break;
    }
    case PROP_COLOR_VALUE: {
      const input = el.matches("input[type=color]")
        ? el
        : el.querySelector<HTMLInputElement>("input[type=color]");
      if (input instanceof HTMLInputElement) {
        input.value = argbToHex(bits);
      }
      break;
    }
    case PROP_BINDING_ID: {
      el.dataset.bindingId = String(bits >>> 0);
      break;
    }
    case PROP_COLOR: {
      // A COLOR / SHAPE node's COLOR property is its fill: it renders as a
      // background (the generic handler below sets the text color, which the
      // Rust SSR renderer also emits alongside the fill).
      const comp = componentByNode.get(el);
      if (comp === COMPONENT_COLOR || comp === COMPONENT_SHAPE) {
        el.style.backgroundColor = argbToRgba(bits);
      }
      applyProperty(el, propId, valueType, bits);
      break;
    }
    case PROP_ENABLED:
      applyEnabled(el, bits);
      break;
    case PROP_ALIGNMENT: {
      // ZStack/grids position on BOTH axes with a 2D code (spec §grid model /
      // §ZStack); stacks/others use the single-axis cross `align-items` token.
      const comp = componentByNode.get(el);
      if (isGridComponent(comp) || comp === COMPONENT_ZSTACK) {
        const code = valueType === VAL_ENUM ? bits & 0xff : Math.round(f32FromBits(bits));
        el.style.justifyItems = alignHCss(code);
        el.style.alignItems = alignVCss(code);
      } else {
        applyProperty(el, propId, valueType, bits);
      }
      break;
    }
    case PROP_GRID_COLUMNS: {
      // A grid's column count (the fixed track of vertical grids): a positive
      // count mirrors into `grid-template-columns` and NEVER into a pixel width
      // (spec §grid model); FILL/absent = auto-fit (no template).
      const comp = componentByNode.get(el);
      const n = f32FromBits(bits);
      if (comp !== COMPONENT_LAZY_HGRID && isGridComponent(comp)) {
        el.style.gridTemplateColumns = n > 0 ? `repeat(${Math.round(n)},minmax(0,1fr))` : "";
      }
      break;
    }
    case PROP_GRID_ROWS: {
      // A grid's row count (the `LAZY_HGRID` fixed track): a positive count
      // mirrors into `grid-template-rows`; FILL/absent = auto-fit.
      const comp = componentByNode.get(el);
      const n = f32FromBits(bits);
      if ((comp === COMPONENT_GRID || comp === COMPONENT_LAZY_HGRID) && isGridComponent(comp)) {
        el.style.gridTemplateRows = n > 0 ? `repeat(${Math.round(n)},minmax(0,1fr))` : "";
      }
      break;
    }
    default:
      applyProperty(el, propId, valueType, bits);
      break;
  }
}

/** Whether `comp` is a grid container (GRID / lazy grids). */
function isGridComponent(comp: number | undefined): boolean {
  return comp === COMPONENT_GRID || comp === COMPONENT_LAZY_VGRID || comp === COMPONENT_LAZY_HGRID;
}

/**
 * A ProgressView's indicator properties: morphs the element between the
 * determinate `<progress>` and the indeterminate `pathland-spinner` div (the
 * Rust renderer's SSR shapes) and applies the determinate value. Mirrors the
 * Rust indeterminate rule: `IS_INDETERMINATE != 0 || PROGRESS < 0`.
 */
function applyProgress(el: HTMLElement, r: DomRenderer, propId: number, valueType: number, bits: number): void {
  const on = valueType === VAL_U8 ? bits & 0xff : bits;
  const indeterminate = propId === PROP_IS_INDETERMINATE ? on !== 0 : f32FromBits(bits) < 0;
  const el2 = morphProgress(el, r, indeterminate);
  if (propId === PROP_PROGRESS && el2 instanceof HTMLProgressElement) {
    const value = Math.min(1, Math.max(0, f32FromBits(bits)));
    el2.value = value;
    el2.max = 1;
  }
}

/** Replace a ProgressView element between its two shapes, preserving attributes and the byId entry. */
function morphProgress(el: HTMLElement, r: DomRenderer, wantSpinner: boolean): HTMLElement {
  const isSpinner = el.classList.contains("pathland-spinner");
  if (wantSpinner === isSpinner) {
    return el;
  }
  const fresh = wantSpinner
    ? (() => {
        const s = document.createElement("div");
        s.className = "pathland-spinner";
        return s;
      })()
    : (() => {
        const p = document.createElement("progress");
        p.max = 1;
        return p;
      })();
  for (const attr of Array.from(el.attributes)) {
    // A spinner is a plain div — it carries no `max`/`value` (the Rust SSR
    // renderer's `<div class="pathland-spinner">`).
    if (wantSpinner && (attr.name === "max" || attr.name === "value")) {
      continue;
    }
    fresh.setAttribute(attr.name, attr.value);
  }
  if (el.parentNode) {
    el.parentNode.replaceChild(fresh, el);
  }
  const id = Number(el.getAttribute("data-pathland-id"));
  if (id) {
    r.byId.set(id, fresh);
  }
  componentByNode.set(fresh, COMPONENT_PROGRESS_VIEW);
  return fresh;
}

// --- media (app-driven AUDIO/VIDEO) ---

/** Per-element media state: echo suppression windows + the last app-requested
 *  playing state (so a source change can resume playback). */
const mediaState = new WeakMap<HTMLMediaElement, {
  suppressUntil: number;
  suppressTimeUntil: number;
  playing: boolean;
  lastReported: number;
  lastReportedVolume: number;
  reportTimer: number;
}>();

/** The media element of a node: the element itself when it IS the media, else the
 *  inner `<audio>`/`<video>` of a `.pathland-media` wrapper. */
function mediaElementOf(el: HTMLElement): HTMLMediaElement | null {
  return el.matches("audio,video")
    ? (el as HTMLMediaElement)
    : el.querySelector<HTMLMediaElement>("audio,video");
}

/** Ensure a media node's container holds an inner (hidden) media element,
 *  creating it for a live-created custom-controls node that lacks one yet. */
function ensureMediaElement(el: HTMLElement, propId: number): HTMLMediaElement | null {
  if (el.matches("audio,video")) {
    return el as HTMLMediaElement;
  }
  let media = el.querySelector<HTMLMediaElement>("audio,video");
  if (!media) {
    media = document.createElement(propId === PROP_VIDEO_SOURCE ? "video" : "audio");
    media.setAttribute("data-pathland-media", "");
    el.prepend(media);
  }
  return media;
}

/** The cadence for `MEDIA_TIME_UPDATED` reports — ~30/s (≈ every 33 ms of
 *  playback progress). The DOM client samples the element's position on this
 *  interval (the browser's `timeupdate` is only ~4 Hz), reporting whenever it
 *  advances; evens out to ~30 reports/s while playing (spec/EVENTS.md Media —
 *  parity with the GTK renderer's 30 Hz gate). Background tabs throttle timers
 *  to ≥1 s, so this is best-effort when not visible/focused. */
const TIME_UPDATE_MAX_INTERVAL_S = 1 / 30;
const TIME_UPDATE_SAMPLE_MS = 33;

/** Attach a media node's element once: wire the app-driven media element to the
 *  host's media-event sink (play/pause/time/ended/volume, spec/EVENTS.md). */
export function setupMediaElement(el: HTMLElement, r: DomRenderer): void {
  const media = mediaElementOf(el);
  if (!media || mediaState.has(media)) {
    return;
  }
  const state = { suppressUntil: 0, suppressTimeUntil: 0, playing: false, lastReported: 0, lastReportedVolume: -1, reportTimer: 0 };
  mediaState.set(media, state);
  const id = Number(el.getAttribute("data-pathland-id"));
  const send = r.onMediaEvent;
  if (!send) {
    return;
  }
  // Play/pause/volume are reported only when the media has NATIVE controls —
  // the only case a user drives them directly. App-driven custom-control media
  // (a hidden element under app controls) never echoes them: every such change
  // is app-initiated, so reporting it back would lock the player state.
  if (media.controls) {
    media.addEventListener("play", () => {
      if (performance.now() >= state.suppressUntil) {
        send(encodeMediaPlayStateChanged(id, true));
      }
    });
    media.addEventListener("pause", () => {
      if (performance.now() >= state.suppressUntil) {
        send(encodeMediaPlayStateChanged(id, false));
      }
    });
    media.addEventListener("volumechange", () => {
      if (performance.now() >= state.suppressUntil) {
        state.lastReportedVolume = media.volume;
        send(encodeMediaVolumeChanged(id, media.volume));
      }
    });
  }
  // Time + ended are always reported: the app displays progress and advances on
  // end. The DOM client SAMPLES the position every ~33 ms (the browser's native
  // `timeupdate` is only ~4 Hz), reporting whenever it advances a cadence step
  // (≈ 30 reports/s while playing; spec/EVENTS.md Media — parity with the GTK
  // renderer's 30 Hz gate). The sampler stops when removed (CMD_DELETE_NODE).
  state.reportTimer = window.setInterval(() => {
    if (!media.paused
        && performance.now() >= state.suppressTimeUntil
        && Math.abs(media.currentTime - state.lastReported) >= TIME_UPDATE_MAX_INTERVAL_S) {
      state.lastReported = media.currentTime;
      send(encodeMediaTimeUpdated(id, media.currentTime));
    }
  }, TIME_UPDATE_SAMPLE_MS);
  media.addEventListener("ended", () => {
    send(encodeMediaEnded(id));
  });
}

/** Test-only: set a media element's last-reported position (the echo-guard
 *  basis for `MEDIA_POSITION` writes, spec/EVENTS.md Media). */
export function __setMediaLastReported(el: HTMLMediaElement, seconds: number): void {
  const state = mediaState.get(el);
  if (state) {
    state.lastReported = seconds;
  }
}

// --- SizeThatFits (FIT_QUERY → local fit → FIT_CHANGED only on transitions) ---

interface FitSlotState {
  thresholds: number[];
  lastIndex: number;
  observer: ResizeObserver | null;
}

/** Per-`SIZE_THAT_FITS` slot state: the candidate thresholds + last reported index. */
const fitState = new WeakMap<HTMLElement, FitSlotState>();

/** The fit rule (spec/PRIMITIVES.md): max i with thresholds[i] <= width;
 *  thresholds ascending, equal thresholds pick the lower index (stable). */
function fitIndexFor(thresholds: number[], width: number): number {
  let selected = 0;
  for (const [i, t] of thresholds.entries()) {
    if (t > width) break;
    if (i === 0 || thresholds[i - 1] !== t) selected = i;
  }
  return selected;
}

