display.text:
// WebSocket transport: connects to the server's reserved `/_pathland/ws`,
// applies each received PLPL batch to the DOM renderer, negotiates the protocol
// version, and reports raw-input events back. Reconnect/backoff, heartbeat, and
// sequence-gap recovery (lost batches without a disconnect → META::RESYNC) live
// here.

import type { Batch } from "./plpl";
import { ProtocolError, parseBatch } from "./plpl";
import { applyBatch, type DomRenderer } from "./apply";
import { encodePing, encodeResync } from "./events";
import { FLAG_HOST_TO_GUEST, VERSION } from "./constants";
import { log } from "./log";
import { describeBatch, describeBatchDetail } from "./describe";

export type TransportStatus = "connecting" | "open" | "reconnecting";

export interface TransportOptions {
  /** WebSocket URL, e.g. `ws://host/_pathland/ws`. */
  url: string;
  /** The retained-node registry deltas are applied to. */
  renderer: DomRenderer;
  /** Invoked after a batch is successfully applied. */
  onBatch?: (batch: Batch) => void;
  onStatus?: (status: TransportStatus) => void;
  /**
   * Invoked on every socket open (first connect and reconnect), before any RESYNC —
   * the DOM client sends its `META::ENVIRONMENT` (viewport + route) here as the first
   * message so the server session seeds from it.
   */
  onOpen?: (transport: Transport) => void;
  /** Injectable socket factory (tests). */
  createSocket?: (url: string) => WebSocket;
}

const BASE_DELAY_MS = 500;
const MAX_DELAY_MS = 30000;
const MAX_ATTEMPTS = 30;

// Heartbeat (spec/OPCODE.md §Transport heartbeat): the client probes server
// liveness with META::PING every HEARTBEAT_INTERVAL_MS. It treats the connection
// as dead when NO server batch of any kind (deltas, META::PONG) has arrived for
// HEARTBEAT_TIMEOUT_MS — a stalled-but-"open" socket never fires onclose, so the
// watchdog forces a close to trigger the reconnect flow (which re-sends the
// environment + requests a META::RESYNC). The PING also counts as inbound WS
// traffic, keeping the connection warm through proxies and idle-spin-down.
const HEARTBEAT_INTERVAL_MS = 5000;
const HEARTBEAT_TIMEOUT_MS = 15000;
const WATCHDOG_CHECK_MS = 1000;

// Numeric readyState (the WebSocket global may be absent in test environments).
const WS_OPEN = 1;

export class Transport {
  private ws: WebSocket | null = null;
  private attempt = 0;
  private stopped = false;
  private readonly options: TransportOptions;
  private pingTimer: ReturnType<typeof setInterval> | null = null;
  private watchdogTimer: ReturnType<typeof setInterval> | null = null;
  private lastActivityAt = 0;
  /**
   * The sequence the next guest → host delta batch must carry, or `null` before
   * the first batch / after a gap or reconnect (re-baseline on the next batch).
   * See spec/OPCODE.md §Sequence gap detection.
   */
  private expectedSequence: number | null = null;

  constructor(options: TransportOptions) {
    this.options = options;
  }

  /** Connect and stay connected (auto-reconnect with exponential backoff). */
  start(): void {
    this.stopped = false;
    this.lastActivityAt = Date.now();
    this.startHeartbeat();
    this.connect();
  }

  /** Permanently close the socket and cancel reconnects. */
  stop(): void {
    this.stopped = true;
    this.stopHeartbeat();
    if (this.ws) {
      this.ws.onclose = null;
      this.ws.close();
      this.ws = null;
    }
  }

  get open(): boolean {
    return this.ws !== null && this.ws.readyState === WS_OPEN;
  }

  send(bytes: Uint8Array): void {
    if (!this.open) {
      return;
    }
    // Best-effort description (never drops the bytes, even if undecodable).
    try {
      const batch = parseBatch(bytes);
      log.info("ws", "→ send", describeBatch(batch));
      log.debug("ws", "→ send detail", describeBatchDetail(batch));
    } catch {
      log.info("ws", "→ send", bytes.length, "bytes");
    }
    this.ws!.send(bytes);
  }

  /** Start the META::PING sender + the no-activity watchdog (one-shot, survives reconnects). */
  private startHeartbeat(): void {
    if (this.pingTimer || this.watchdogTimer) {
      return;
    }
    this.pingTimer = setInterval(() => {
      if (this.open) {
        this.send(encodePing());
      }
    }, HEARTBEAT_INTERVAL_MS);
    this.watchdogTimer = setInterval(() => {
      if (!this.open) {
        return;
      }
      if (Date.now() - this.lastActivityAt > HEARTBEAT_TIMEOUT_MS) {
        log.warn("ws", `no server frame for ${HEARTBEAT_TIMEOUT_MS} ms — reconnecting`);
        this.ws?.close();
      }
    }, WATCHDOG_CHECK_MS);
  }

  private stopHeartbeat(): void {
    if (this.pingTimer) {
      clearInterval(this.pingTimer);
      this.pingTimer = null;
    }
    if (this.watchdogTimer) {
      clearInterval(this.watchdogTimer);
      this.watchdogTimer = null;
    }
  }

  private connect(): void {
    log.debug("ws", "connecting", this.options.url);
    const ws = this.options.createSocket
      ? this.options.createSocket(this.options.url)
      : new WebSocket(this.options.url);
    this.ws = ws;
    ws.binaryType = "arraybuffer";
    ws.onopen = () => {
      // A reconnect means the client missed deltas while disconnected: request a
      // full snapshot (META::RESYNC). The first connect never does — the client
      // already has the whole UI from the SSR HTML. On EVERY open (before any
      // resync) the client sends its environment (viewport + route).
      this.lastActivityAt = Date.now();
      // Re-baseline the sequence on the next guest → host batch (a fresh
      // connection's stream restarts; see §Sequence gap detection).
      this.expectedSequence = null;
      const reconnected = this.attempt > 0;
      this.attempt = 0;
      log.info("ws", reconnected ? "connected (reconnect)" : "connected");
      this.options.onStatus?.("open");
      this.options.onOpen?.(this);
      if (reconnected) {
        log.debug("ws", "requesting RESYNC (missed deltas while disconnected)");
        this.send(encodeResync());
      }
    };
    ws.onmessage = (event) => this.handleMessage(event.data);
    ws.onerror = () => {
      log.error("ws", "socket error");
      // onclose always follows; nothing to do here.
    };
    ws.onclose = () => {
      this.ws = null;
      if (this.stopped) {
        log.debug("ws", "closed (stopped)");
        return;
      }
      log.info("ws", "closed — reconnecting (attempt", this.attempt + 1 + ")");
      this.options.onStatus?.("reconnecting");
      this.scheduleReconnect();
    };
  }

  private scheduleReconnect(): void {
    if (this.attempt >= MAX_ATTEMPTS) {
      return;
    }
    const delay = Math.min(BASE_DELAY_MS * 2 ** this.attempt, MAX_DELAY_MS);
    this.attempt++;
    setTimeout(() => this.connect(), delay);
  }

  private handleMessage(data: unknown): void {
    // Any server batch (a delta, a META::PONG, anything) proves the connection
    // is alive — reset the heartbeat watchdog.
    this.lastActivityAt = Date.now();
    let bytes: Uint8Array;
    if (data instanceof ArrayBuffer) {
      bytes = new Uint8Array(data);
    } else if (data instanceof Blob) {
      void data.arrayBuffer().then((buffer) => this.handleMessage(buffer));
      return;
    } else {
      bytes = new Uint8Array(0);
    }
    let batch: Batch;
    try {
      batch = parseBatch(bytes);
    } catch (err) {
      if (err instanceof ProtocolError) {
        log.error("ws", "rejected batch:", err.message);
        return;
      }
      throw err;
    }
    log.info("ws", "← recv", describeBatch(batch));
    log.debug("ws", "← recv detail", describeBatchDetail(batch));
    if (batch.version !== VERSION) {
      log.warn("ws", `protocol version ${batch.version} != ${VERSION}; reloading`);
      location.reload();
      return;
    }
    // Sequence gap detection (spec/OPCODE.md §Sequence gap detection): a
    // guest → host delta batch whose sequence breaks the chain means one or more
    // batches were lost while the socket stayed open. Do not apply the gapped
    // batch (its deltas assume the lost state); request a full snapshot and
    // re-baseline on the next batch.
    if (this.isSequenceGap(batch)) {
      log.warn(
        "ws",
        `sequence gap: expected ${this.expectedSequence}, got ${batch.sequence} — requesting RESYNC`,
      );
      this.expectedSequence = null;
      this.send(encodeResync());
      return;
    }
    this.trackSequence(batch);
    try {
      applyBatch(batch, this.options.renderer);
    } catch (err) {
      if (err instanceof ProtocolError) {
        log.error("ws", "rejected delta:", err.message);
        return;
      }
      throw err;
    }
    this.options.onBatch?.(batch);
  }

  /**
   * True when a guest → host delta batch breaks the expected sequence chain.
   * Host → guest batches (heartbeat `PONG`, request echoes) carry sequence 0 and
   * are not part of the guest → host stream, so they are ignored here.
   */
  private isSequenceGap(batch: Batch): boolean {
    if ((batch.flags & FLAG_HOST_TO_GUEST) !== 0) {
      return false;
    }
    return this.expectedSequence !== null && batch.sequence !== this.expectedSequence;
  }

  /** Advance the expected sequence from a guest → host delta batch (baseline or next). */
  private trackSequence(batch: Batch): void {
    if ((batch.flags & FLAG_HOST_TO_GUEST) !== 0) {
      return;
    }
    this.expectedSequence = batch.sequence + 1;
  }
}

// The DOM renderer's native element mapping: create the DOM shell for a node of
// the given component. Used when TREE deltas create nodes at runtime (the SSR
// path renders the shell server-side with Tailwind classes).

import {
  COMPONENT_AUDIO,
  COMPONENT_BUTTON,
  COMPONENT_COLOR,
  COMPONENT_COLOR_PICKER,
  COMPONENT_COMMENT,
  COMPONENT_DATE_PICKER,
  COMPONENT_DIVIDER,
  COMPONENT_GAUGE,
  COMPONENT_GRID,
  COMPONENT_GRID_ROW,
  COMPONENT_HSTACK,
  COMPONENT_ICON,
  COMPONENT_IMAGE,
  COMPONENT_LAZY_HGRID,
  COMPONENT_LAZY_HSTACK,
  COMPONENT_LAZY_VGRID,
  COMPONENT_LAZY_VSTACK,
  COMPONENT_MENU,
  COMPONENT_PICKER,
  COMPONENT_PROGRESS_VIEW,
  COMPONENT_SCROLLVIEW,
  COMPONENT_SIZE_THAT_FITS,
  COMPONENT_SHAPE,
  COMPONENT_SLIDER,
  COMPONENT_SPACER,
  COMPONENT_STEPPER,
  COMPONENT_TEXT,
  COMPONENT_TEXT_EDITOR,
  COMPONENT_TEXT_FIELD,
  COMPONENT_TOGGLE,
  COMPONENT_VIDEO,
  COMPONENT_VSTACK,
  COMPONENT_ZSTACK,
} from "./constants";

/** Create the DOM shell for a node of {@code component}. Returns a Node (elements or an inert comment). */
export function createElement(component: number): Node {
  switch (component) {
    case COMPONENT_VSTACK:
    case COMPONENT_LAZY_VSTACK:
      return flexBox("column");
    case COMPONENT_HSTACK:
    case COMPONENT_LAZY_HSTACK:
      return flexBox("row");
    case COMPONENT_ZSTACK: {
      // ZStack (SwiftUI ZStack / Compose Box): an overlapping grid — children
      // share one cell (`grid-area:1/1`) and are positioned per ALIGNMENT
      // (mirrors the Rust SSR renderer). The container's size (hug-to-largest-
      // child / Fixed / FILL / fill-propagation) is resolved by the layout pass.
      const el = document.createElement("div");
      el.style.display = "grid";
      el.style.isolation = "isolate";
      el.style.gridTemplateColumns = "minmax(0,1fr)";
      el.style.gridTemplateRows = "minmax(0,1fr)";
      // Position children on both axes per the ZSTACK ALIGNMENT (default start).
      el.style.justifyItems = "start";
      el.style.alignItems = "start";
      return el;
    }
    case COMPONENT_GRID:
    case COMPONENT_LAZY_VGRID:
    case COMPONENT_LAZY_HGRID: {
      const el = document.createElement("div");
      el.style.display = "grid";
      // Cells keep their size and position within their tracks (spec §grid
      // model); `justify-items`/`align-items` come from the grid ALIGNMENT.
      el.style.justifyItems = "start";
      el.style.alignItems = "start";
      // Lazy horizontal grids flow into auto columns (mirrors the Rust SSR
      // renderer's `grid-auto-flow:column;grid-auto-columns:1fr`).
      if (component === COMPONENT_LAZY_HGRID) {
        el.style.gridAutoFlow = "column";
        el.style.gridAutoColumns = "minmax(0,1fr)";
      }
      return el;
    }
    case COMPONENT_GRID_ROW: {
      // A grid's explicit row grouping (spec §GridRow): transparent
      // (`display:contents`) — its cell children participate in the parent
      // GRID's layout (mirrors the Rust SSR renderer). Renders nothing outside
      // a GRID.
      const el = document.createElement("div");
      el.style.display = "contents";
      return el;
    }
    case COMPONENT_SCROLLVIEW: {
      const el = document.createElement("div");
      // Layout-greedy on both axes (LAYOUT.md): a scroll region fills the
      // available space (mirrors the Rust SSR renderer).
      el.style.flex = "1 1 auto";
      el.style.alignSelf = "stretch";
      el.style.overflow = "auto";
      return el;
    }
    case COMPONENT_SIZE_THAT_FITS: {
      // A fit slot: size-taking (fills the parent's proposal — the measured width
      // is the fitting unit) with a `data-pathland-fit`-reflected threshold table.
      // Layout-transparent: forwards the parent flex container's settings
      // (`inherit`) so the sole candidate is laid out as if it sat directly in the
      // parent (e.g. a centered VStack keeps centering a slot-wrapped HSTACK);
      // mirrors the Rust SSR renderer's slot styles.
      const el = document.createElement("div");
      el.className = "pathland-ftf";
      el.style.display = "flex";
      el.style.flexDirection = "inherit";
      el.style.alignItems = "inherit";
      el.style.justifyContent = "inherit";
      el.style.flex = "1 1 auto";
      el.style.alignSelf = "stretch";
      el.style.minWidth = "0";
      el.style.minHeight = "0";
      return el;
    }
    case COMPONENT_TEXT:
      return document.createElement("span");
    case COMPONENT_BUTTON: {
      const el = document.createElement("button");
      el.className = "pathland-button"; // mirror the Rust renderer's SSR class
      return el;
    }
    case COMPONENT_IMAGE: {
      const el = document.createElement("img");
      el.alt = "";
      return el;
    }
    case COMPONENT_ICON: {
      // A semantic icon: a **filled** Remix-style inline SVG shell (mirrors the
      // Rust SSR's `WEB_SVG_OPEN`). The inner markup + aria come from the
      // ICON_NAME / LABEL deltas.
      const el = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      el.setAttribute("xmlns", "http://www.w3.org/2000/svg");
      el.setAttribute("class", "pathland-icon");
      el.setAttribute("viewBox", "0 0 24 24");
      el.setAttribute("fill", "currentColor");
      el.setAttribute("aria-hidden", "true");
      el.setAttribute("focusable", "false");
      return el;
    }
    case COMPONENT_AUDIO: {
      // A bare media element: native (no children) gets `controls` in apply; a
      // node that gains custom control children is morphed to a
      // `.pathland-media` wrapper on first insert (mirrors the Rust SSR).
      return document.createElement("audio");
    }
    case COMPONENT_VIDEO: {
      return document.createElement("video");
    }
    case COMPONENT_COLOR: {
      // Layout-greedy (SwiftUI Color): expands to the available space unless a
      // size modifier constrains it (mirrors the Rust SSR renderer's
      // `flex:1 1 auto;align-self:stretch`).
      const el = document.createElement("div");
      el.style.flex = "1 1 auto";
      el.style.alignSelf = "stretch";
      return el;
    }
    case COMPONENT_SHAPE:
      return document.createElement("div");
    case COMPONENT_GAUGE: {
      // `<div class="pathland-gauge"><div></div></div>` — the bar width is set from
      // the VALUE property at apply time (mirrors the Rust renderer's SSR markup).
      const el = document.createElement("div");
      el.className = "pathland-gauge";
      el.append(document.createElement("div"));
      return el;
    }
    case COMPONENT_DIVIDER: {
      // `<div style="height:0;width:100%;border-top:1px solid rgba(0,0,0,0.2)">`
      // — mirrors the Rust SSR renderer's default divider (greedy on the cross
      // axis, LAYOUT.md). BORDER_WIDTH / COLOR deltas override border-top.
      const el = document.createElement("div");
      el.style.height = "0";
      el.style.width = "100%";
      el.style.borderTop = "1px solid rgba(0,0,0,0.2)";
      return el;
    }
    case COMPONENT_SPACER: {
      const el = document.createElement("div");
      el.style.flex = "1";
      return el;
    }
    case COMPONENT_PROGRESS_VIEW: {
      const el = document.createElement("progress");
      el.max = 1;
      return el;
    }
    case COMPONENT_TEXT_EDITOR: {
      const el = document.createElement("textarea");
      el.className = "pathland-input";
      el.setAttribute("rows", "4"); // mirrors the Rust SSR renderer
      return el;
    }
    case COMPONENT_TEXT_FIELD:
      return textFieldShell();
    case COMPONENT_TOGGLE:
      return toggleShell();
    case COMPONENT_SLIDER:
      return sliderShell();
    case COMPONENT_STEPPER:
      return stepperShell();
    case COMPONENT_PICKER:
      return document.createElement("select");
    case COMPONENT_MENU:
      return menuShell();
    case COMPONENT_COLOR_PICKER: {
      const el = document.createElement("input");
      el.type = "color";
      return el;
    }
    case COMPONENT_DATE_PICKER: {
      const el = document.createElement("input");
      el.type = "date";
      return el;
    }
    case COMPONENT_COMMENT:
      return document.createComment("");
    default:
      return document.createElement("div");
  }
}

function flexBox(direction: "column" | "row"): HTMLElement {
  const el = document.createElement("div");
  el.style.display = "flex";
  el.style.flexDirection = direction;
  // Cross-axis default is hug (flex-start) — mirrors the Rust SSR renderer's
  // `align-items` when no ALIGNMENT property is set (LAYOUT.md: never CSS
  // stretch; only FILL-sized children stretch). An ALIGNMENT delta overrides it.
  el.style.alignItems = "flex-start";
  return el;
}

/** `<label class="pathland-textfield"><span class="pathland-label"></span><input type="text"></label>` */
function textFieldShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-textfield";
  const span = document.createElement("span");
  span.className = "pathland-label";
  const input = document.createElement("input");
  input.type = "text";
  input.className = "pathland-input";
  label.append(span, input);
  return label;
}

/** `<label class="pathland-toggle"><input type="checkbox"><span class="pathland-text"></span></label>` */
function toggleShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-toggle";
  const input = document.createElement("input");
  input.type = "checkbox";
  const span = document.createElement("span");
  span.className = "pathland-text";
  label.append(input, span);
  return label;
}

/** `<label class="pathland-slider"><input type="range" step="any"><span class="pathland-text"></span></label>` */
function sliderShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-slider";
  const input = document.createElement("input");
  input.type = "range";
  input.step = "any";
  const span = document.createElement("span");
  span.className = "pathland-text";
  label.append(input, span);
  return label;
}

/** `<div class="pathland-stepper"><button data-step="-1">−</button><span></span><button data-step="1">+</button><span class="pathland-stepper-range" hidden></span></div>` */
function stepperShell(): HTMLElement {
  const el = document.createElement("div");
  el.className = "pathland-stepper";
  const minus = document.createElement("button");
  minus.type = "button";
  minus.dataset.step = "-1";
  minus.textContent = "−";
  const value = document.createElement("span");
  const plus = document.createElement("button");
  plus.type = "button";
  plus.dataset.step = "1";
  plus.textContent = "+";
  const range = document.createElement("span");
  range.className = "pathland-stepper-range";
  range.hidden = true;
  el.append(minus, value, plus, range);
  return el;
}

/** `<div class="pathland-menu"><div class="pathland-menu-trigger"></div><div class="pathland-menu-items"></div></div>` */
function menuShell(): HTMLElement {
  const el = document.createElement("div");
  el.className = "pathland-menu";
  // `role="menu"` is the control's intrinsic semantics (mirrors the Rust SSR
  // renderer); the `ROLE` property no longer carries control roles.
  el.setAttribute("role", "menu");
  const trigger = document.createElement("div");
  trigger.className = "pathland-menu-trigger";
  const items = document.createElement("div");
  items.className = "pathland-menu-items";
  el.append(trigger, items);
  return el;
}

/**
 * The container a node's TREE children are inserted into. Most nodes append
 * children directly; composite shells route them into their label/trigger span.
 */
export function childrenContainer(node: Node): Node | null {
  if (node instanceof HTMLElement) {
    if (node.classList.contains("pathland-menu")) {
      return node.querySelector(".pathland-menu-items");
    }
    if (node.classList.contains("pathland-toggle") || node.classList.contains("pathland-slider")) {
      return node.querySelector(".pathland-text");
    }
    if (node.classList.contains("pathland-textfield")) {
      return node.querySelector(".pathland-label");
    }
  }
  return node;
}

// Host → guest event encoders. Each call produces a self-contained PLPL batch
// with a single EVENT opcode (guest → host direction, flags = 0x0000).

import {
  CAT_EVENT,
  CAT_META,
  CMD_DATE_CHANGED,
  CMD_EDITING_CHANGED,
  CMD_ENVIRONMENT,
  CMD_FOCUS_CHANGED,
  CMD_KEY_DOWN,
  CMD_KEY_UP,
  CMD_MEDIA_ENDED,
  CMD_MEDIA_PLAY_STATE_CHANGED,
  CMD_MEDIA_TIME_UPDATED,
  CMD_MEDIA_VOLUME_CHANGED,
  CMD_FIT_CHANGED,
  CMD_NAVIGATE,
  CMD_PING,
  CMD_POINTER_DOWN,
  CMD_POINTER_MOVE,
  CMD_POINTER_UP,
  CMD_RESYNC,
  CMD_SCROLL,
  CMD_SUBMIT,
  CMD_TEXT_CHANGED,
  CMD_VALUE_CHANGED,
  CMD_WHEEL,
  ENV_ROUTE,
  ENV_VIEWPORT_HEIGHT,
  ENV_VIEWPORT_WIDTH,
  FLAG_HOST_TO_GUEST,
  FLAG_NAVIGATE_URL,
  HEADER_SIZE,
  MAGIC,
  OPCODE_SIZE,
  VERSION,
} from "./constants";
import { bitsFromF32 } from "./format";

function eventBatch(command: number, a: number, b: number, c: number, opcodeFlags = 0): Uint8Array {
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true); // batch flags = guest -> host
  view.setUint32(8, 0, true); // sequence (0: not a delta batch)
  view.setUint32(12, 1, true); // opcodeCount
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_EVENT);
  view.setUint8(pos + 1, command);
  view.setUint16(pos + 2, opcodeFlags, true);
  view.setUint32(pos + 4, a, true);
  view.setUint32(pos + 8, b, true);
  view.setUint32(pos + 12, c, true);
  return out;
}

/** A META::RESYNC request (host → guest): ask the server for a full snapshot of the current tree. */
export function encodeResync(): Uint8Array {
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0x0001, true); // batch flags = HOST_TO_GUEST
  view.setUint32(8, 0, true); // sequence (0: not a delta batch)
  view.setUint32(12, 1, true); // opcodeCount
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_META);
  view.setUint8(pos + 1, CMD_RESYNC);
  view.setUint32(pos + 4, 0, true);
  view.setUint32(pos + 8, 0, true);
  view.setUint32(pos + 12, 0, true);
  return out;
}

/** A META::PING transport-liveness heartbeat probe (guest → host, spec/OPCODE.md §Transport heartbeat). */
export function encodePing(): Uint8Array {
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0x0000, true); // batch flags = guest -> host
  view.setUint32(8, 0, true); // sequence (0: not a delta batch)
  view.setUint32(12, 1, true); // opcodeCount
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_META);
  view.setUint8(pos + 1, CMD_PING);
  view.setUint16(pos + 2, 0, true);
  view.setUint32(pos + 4, 0, true);
  view.setUint32(pos + 8, 0, true);
  view.setUint32(pos + 12, 0, true);
  return out;
}

// --- pointer ---

/** A button press: POINTER_DOWN at viewport-relative x/y (f32). */
export function encodePointerDown(target: number, x: number, y: number, flags = 0): Uint8Array {
  return eventBatch(CMD_POINTER_DOWN, target, bitsFromF32(x), bitsFromF32(y), flags);
}

/** A pointer move / hover enter-leave at viewport-relative x/y. */
export function encodePointerMove(target: number, x: number, y: number, flags: number): Uint8Array {
  return eventBatch(CMD_POINTER_MOVE, target, bitsFromF32(x), bitsFromF32(y), flags);
}

/** A button release: POINTER_UP at viewport-relative x/y. */
export function encodePointerUp(target: number, x: number, y: number, flags = 0): Uint8Array {
  return eventBatch(CMD_POINTER_UP, target, bitsFromF32(x), bitsFromF32(y), flags);
}

// --- keyboard ---

/** KEY_DOWN (A=target, B=keyCode u16 low, C=modifiers u8 low, flag KEY_REPEAT). */
export function encodeKeyDown(target: number, keyCode: number, modifiers: number, repeat = false): Uint8Array {
  return eventBatch(CMD_KEY_DOWN, target, keyCode & 0xffff, modifiers & 0xff, repeat ? 0x0002 : 0);
}

/** KEY_UP (A=target, B=keyCode u16 low, C=modifiers u8 low). */
export function encodeKeyUp(target: number, keyCode: number, modifiers: number): Uint8Array {
  return eventBatch(CMD_KEY_UP, target, keyCode & 0xffff, modifiers & 0xff);
}

// --- value / text / date ---

/** A VALUE_CHANGED EVENT with the value as f32 bits (toggle 0/1, slider, select index, stepper). */
export function encodeValueChanged(target: number, value: number): Uint8Array {
  return eventBatch(CMD_VALUE_CHANGED, target, bitsFromF32(value), 0);
}

/** A VALUE_CHANGED EVENT with a raw 32-bit payload (e.g. a packed ARGB color). */
export function encodeValueBits(target: number, bits: number): Uint8Array {
  return eventBatch(CMD_VALUE_CHANGED, target, bits >>> 0, 0);
}

// --- media ---

/** A bound media node's play state changed (B = 0/1). */
export function encodeMediaPlayStateChanged(target: number, playing: boolean): Uint8Array {
  return eventBatch(CMD_MEDIA_PLAY_STATE_CHANGED, target, playing ? 1 : 0, 0);
}

/** A bound media node's current position (B = seconds, f32). */
export function encodeMediaTimeUpdated(target: number, seconds: number): Uint8Array {
  return eventBatch(CMD_MEDIA_TIME_UPDATED, target, bitsFromF32(seconds), 0);
}

/** A bound media node reached the end of its media. */
export function encodeMediaEnded(target: number): Uint8Array {
  return eventBatch(CMD_MEDIA_ENDED, target, 0, 0);
}

/** A bound media node's volume changed (B = 0..1, f32). */
export function encodeMediaVolumeChanged(target: number, volume: number): Uint8Array {
  return eventBatch(CMD_MEDIA_VOLUME_CHANGED, target, bitsFromF32(volume), 0);
}

/** A `SIZE_THAT_FITS` slot's selected candidate changed (B = index, f32). */
export function encodeFittedChanged(target: number, index: number): Uint8Array {
  return eventBatch(CMD_FIT_CHANGED, target, bitsFromF32(index), 0);
}

/** A DATE_CHANGED EVENT (A=target, B=days, C=millis of day). */
export function encodeDateChanged(target: number, days: number, millis: number): Uint8Array {
  return eventBatch(CMD_DATE_CHANGED, target, days >>> 0, millis >>> 0);
}

/** A TEXT_CHANGED EVENT; the text rides in the batch's string section (B = relative offset). */
export function encodeTextChanged(target: number, text: string): Uint8Array {
  const bytes = new TextEncoder().encode(text);
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4 + 4 + bytes.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(8, 0, true);
  view.setUint32(12, 1, true);
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_EVENT);
  view.setUint8(pos + 1, CMD_TEXT_CHANGED);
  view.setUint32(pos + 4, target, true);
  view.setUint32(pos + 8, 0, true); // b = relative string offset (first entry)
  view.setUint32(pos + 12, 0, true);
  // string section: [stringsLen u32][entryLen u32][utf8…]
  const stringsAt = HEADER_SIZE + OPCODE_SIZE;
  view.setUint32(stringsAt, 4 + bytes.length, true);
  view.setUint32(stringsAt + 4, bytes.length, true);
  out.set(bytes, stringsAt + 8);
  return out;
}

// --- focus / editing / submit / scroll / wheel ---

/** FOCUS_CHANGED (A=target, B=focused 0/1). */
export function encodeFocusChanged(target: number, focused: boolean): Uint8Array {
  return eventBatch(CMD_FOCUS_CHANGED, target, focused ? 1 : 0, 0);
}

/** EDITING_CHANGED (A=target, B=editing 0/1). */
export function encodeEditingChanged(target: number, editing: boolean): Uint8Array {
  return eventBatch(CMD_EDITING_CHANGED, target, editing ? 1 : 0, 0);
}

/** SUBMIT (A=target). */
export function encodeSubmit(target: number): Uint8Array {
  return eventBatch(CMD_SUBMIT, target, 0, 0);
}

/** SCROLL (A=target, B=offsetX f32, C=offsetY f32). */
export function encodeScroll(target: number, offsetX: number, offsetY: number): Uint8Array {
  return eventBatch(CMD_SCROLL, target, bitsFromF32(offsetX), bitsFromF32(offsetY));
}

/** WHEEL (A=target, B=deltaX f32, C=deltaY f32). */
export function encodeWheel(target: number, deltaX: number, deltaY: number): Uint8Array {
  return eventBatch(CMD_WHEEL, target, bitsFromF32(deltaX), bitsFromF32(deltaY));
}

// --- navigation (global, not node-keyed) ---

/** NAVIGATE to a URL (browser back/forward `popstate`, a deep link); the URL rides the string section. */
export function encodeNavigate(url: string): Uint8Array {
  const bytes = new TextEncoder().encode(url);
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4 + 4 + bytes.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(8, 0, true);
  view.setUint32(12, 1, true);
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_EVENT);
  view.setUint8(pos + 1, CMD_NAVIGATE);
  view.setUint16(pos + 2, FLAG_NAVIGATE_URL, true);
  view.setUint32(pos + 4, 0, true); // no target — global
  view.setUint32(pos + 8, 0, true); // b = relative string offset (first entry)
  view.setUint32(pos + 12, 0, true);
  const stringsAt = HEADER_SIZE + OPCODE_SIZE;
  view.setUint32(stringsAt, 4 + bytes.length, true);
  view.setUint32(stringsAt + 4, bytes.length, true);
  out.set(bytes, stringsAt + 8);
  return out;
}

/** NAVIGATE with no URL: a native back request (the app pops its own back-stack). */
export function encodeNavigateBack(): Uint8Array {
  return eventBatch(CMD_NAVIGATE, 0, 0, 0);
}

// --- environment (host → guest; META::ENVIRONMENT field family, spec/OPCODE.md) ---

/**
 * The platform's environment: viewport + initial route, as a batch of
 * `META::ENVIRONMENT` field opcodes (the route rides the batch's string section).
 * The DOM client sends this as its **first** message on connect and re-sends it to
 * **enrich** the environment after connect (e.g. a window resize re-emits the
 * viewport fields). The SSR host synthesizes the same message from the HTTP request.
 */
export function encodeEnvironment(width: number, height: number, route: string): Uint8Array {
  const routeBytes = new TextEncoder().encode(route);
  const out = new Uint8Array(HEADER_SIZE + 3 * OPCODE_SIZE + 4 + 4 + routeBytes.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, FLAG_HOST_TO_GUEST, true); // host (renderer) -> app
  view.setUint32(8, 0, true);
  view.setUint32(12, 3, true); // VIEWPORT_WIDTH, VIEWPORT_HEIGHT, ROUTE
  let pos = HEADER_SIZE;
  const field = (id: number, b: number) => {
    view.setUint8(pos, CAT_META);
    view.setUint8(pos + 1, CMD_ENVIRONMENT);
    view.setUint16(pos + 2, 0, true);
    view.setUint32(pos + 4, id, true);
    view.setUint32(pos + 8, b, true);
    view.setUint32(pos + 12, 0, true);
    pos += OPCODE_SIZE;
  };
  field(ENV_VIEWPORT_WIDTH, bitsFromF32(width));
  field(ENV_VIEWPORT_HEIGHT, bitsFromF32(height));
  field(ENV_ROUTE, 0); // route string at relative offset 0
  const stringsAt = pos;
  view.setUint32(stringsAt, 4 + routeBytes.length, true);
  view.setUint32(stringsAt + 4, routeBytes.length, true);
  out.set(routeBytes, stringsAt + 8);
  return out;
}

