import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { applyBatch, setNodeText, setupMediaElement, updateNavBackButtons, __setMediaLastReported, type DomRenderer } from "../src/apply";
import { clearInFlightRange, markRangeInFlight } from "../src/inFlight";
import { parseBatch } from "../src/plpl";
import {
  CAT_META,
  CAT_PARAMETER,
  CAT_TREE,
  CMD_CREATE_NODE,
  CMD_DELETE_NODE,
  CMD_INSERT_CHILD,
  CMD_MOVE_CHILD,
  CMD_RESET,
  CMD_SET_DATE,
  CMD_SET_DESIGN_TOKEN,
  CMD_SET_PROPERTY,
  CMD_SET_TEXT,
  COMPONENT_BUTTON,
  COMPONENT_GRID,
  COMPONENT_LAZY_HGRID,
  COMPONENT_MENU,
  COMPONENT_PROGRESS_VIEW,
  COMPONENT_TEXT,
  COMPONENT_VSTACK,
  COMPONENT_ZSTACK,
  COMPONENT_ICON,
  ALIGN_TOP_TRAILING,
  PROP_ALIGNMENT,
  PROP_AUDIO_SOURCE,
  PROP_COLOR,
  PROP_FONT_SIZE,
  PROP_FONT_WEIGHT,
  PROP_GRID_COLUMNS,
  PROP_GRID_ROWS,
  PROP_ICON_NAME,
  PROP_IMAGE_SOURCE,
  PROP_IS_INDETERMINATE,
  PROP_LABEL,
  PROP_LINE_LIMIT,
  PROP_MEDIA_POSITION,
  PROP_NAV_CHROME,
  PROP_PLAYBACK_STATE,
  PROP_NAV_DEPTH,
  PROP_PROGRESS,
  PROP_ROUTE,
  PROP_SELECTED,
  PROP_SPACING,
  PROP_TEXT,
  PROP_ROLE,
  PROP_TEXT_STYLE,
  PROP_VALUE,
  PROP_Z_INDEX,
  ROLE_BANNER,
  ROLE_HEADER,
  TEXT_STYLE_LARGE_TITLE,
  TEXT_STYLE_SUBHEADLINE,
  TEXT_STYLE_TITLE2,
  VAL_DESIGN_TOKEN,
  VAL_F32,
  VAL_STRING,
  VAL_U32,
  VAL_U8,
} from "../src/constants";
import { buildBatch, stringEntry } from "./plpl.test";

const f32bits = (v: number): number => new Uint32Array(new Float32Array([v]).buffer)[0] ?? 0;

beforeEach(() => {
  document.head.querySelectorAll("style[data-pathland-tokens]").forEach((s) => s.remove());
});

function renderer(): DomRenderer {
  return { byId: new Map<number, Node>() };
}

/** The lazy icon resolver must not hit the network in these tests. */
function noNetworkIcons() {
  vi.stubGlobal("fetch", async () => ({ ok: false, text: async () => "" }));
}

afterEach(() => {
  vi.useRealTimers();
  vi.unstubAllGlobals();
});

/** Drop an SSR-style embedded glyph into the document (what a hydrated page carries). */
function seedGlyph(name: string, inner: string): void {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("class", "pathland-icon");
  svg.setAttribute("data-pathland-icon", name);
  svg.innerHTML = inner;
  document.body.appendChild(svg);
}

describe("applyBatch · media", () => {
  it("seeks only on a meaningful MEDIA_POSITION change (no echo interruption)", () => {
    const wrapper = document.createElement("div");
    wrapper.className = "pathland-media";
    wrapper.setAttribute("data-pathland-id", "1");
    wrapper.setAttribute("data-pathland-media", "");
    const audio = document.createElement("audio");
    wrapper.appendChild(audio);
    document.body.appendChild(wrapper);
    const r = renderer();
    r.byId.set(1, wrapper);

    // A near-identical position (a timeupdate echo) must NOT seek the element —
    // even when the network delay means the element's currentTime has advanced
    // past the reported position (the guard compares against the last-reported
    // position, not currentTime).
    setupMediaElement(wrapper, r);
    audio.currentTime = 3.5;
    __setMediaLastReported(audio, 3);
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
      ((VAL_F32 << 16) | PROP_MEDIA_POSITION) >>> 0, f32bits(3.1)]], stringEntry(""))), r);
    expect(audio.currentTime).toBe(3.5);

    // A real seek (a user drag) does.
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
      ((VAL_F32 << 16) | PROP_MEDIA_POSITION) >>> 0, f32bits(120)]], stringEntry(""))), r);
    expect(audio.currentTime).toBe(120);
  });

  it("resumes playback when the source changes while playing (a skip keeps playing)", () => {
    const wrapper = document.createElement("div");
    wrapper.className = "pathland-media";
    wrapper.setAttribute("data-pathland-id", "1");
    wrapper.setAttribute("data-pathland-media", "");
    const audio = document.createElement("audio");
    wrapper.appendChild(audio);
    document.body.appendChild(wrapper);
    const r = renderer();
    r.byId.set(1, wrapper);

    // App requests playing -> the element plays.
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
      ((VAL_U32 << 16) | PROP_PLAYBACK_STATE) >>> 0, 1]], stringEntry(""))), r);
    expect(audio.paused).toBe(false);

    // A source change (skip/auto-advance) resets the element to paused...
    audio.pause();
    // ...and applying the new source resumes playback.
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
      ((VAL_STRING << 16) | PROP_AUDIO_SOURCE) >>> 0, 0]], stringEntry("/track2.mp3"))), r);
    expect(audio.paused).toBe(false);
  });

  it("reports MEDIA_TIME_UPDATED at ~30/s (a 33 ms position sampler)", () => {
    vi.useFakeTimers();
    const wrapper = document.createElement("div");
    wrapper.className = "pathland-media";
    wrapper.setAttribute("data-pathland-id", "1");
    wrapper.setAttribute("data-pathland-media", "");
    const audio = document.createElement("audio");
    wrapper.appendChild(audio);
    document.body.appendChild(wrapper);
    const sent: Uint8Array[] = [];
    const r = renderer();
    r.byId.set(1, wrapper);
    r.onMediaEvent = (batch: Uint8Array) => sent.push(batch);

    // Wire the media element and start "playing" (paused=false for the gate).
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
      ((VAL_U32 << 16) | PROP_PLAYBACK_STATE) >>> 0, 1]], stringEntry(""))), r);

    // The first sample establishes the baseline report (last 0 → 0.04 s).
    audio.currentTime = 0.04;
    vi.advanceTimersByTime(40);
    expect(sent).toHaveLength(1);

    // A sub-step advance (< ~33 ms of progress) is dropped on the next tick.
    audio.currentTime = 0.05;
    vi.advanceTimersByTime(40);
    expect(sent).toHaveLength(1);

    // A real ~1/30 s step per tick reports again (~30 samples/s).
    audio.currentTime = 0.10;
    vi.advanceTimersByTime(40);
    expect(sent).toHaveLength(2);
  });

  it("removing a media node clears its 30 Hz position sampler", () => {
    vi.useFakeTimers();
    const wrapper = document.createElement("div");
    wrapper.className = "pathland-media";
    wrapper.setAttribute("data-pathland-id", "1");
    wrapper.setAttribute("data-pathland-media", "");
    const audio = document.createElement("audio");
    wrapper.appendChild(audio);
    document.body.appendChild(wrapper);
    const sent: Uint8Array[] = [];
    const r = renderer();
    r.byId.set(1, wrapper);
    r.onMediaEvent = (batch: Uint8Array) => sent.push(batch);
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
      ((VAL_U32 << 16) | PROP_PLAYBACK_STATE) >>> 0, 1]], stringEntry(""))), r);

    // Delete the node: the sampler must stop (no reports after deletion,
    // even as the position advances and time passes).
    applyBatch(parseBatch(buildBatch([[CAT_TREE, CMD_DELETE_NODE, 0, 1]])), r);
    audio.currentTime = 5;
    vi.advanceTimersByTime(120);
    expect(sent).toHaveLength(0);
  });
});

describe("applyBatch · STYLE", () => {
  it("applies SET_TEXT to a hydrated span", () => {
    const span = document.createElement("span");
    span.setAttribute("data-pathland-id", "1");
    const r = renderer();
    r.byId.set(1, span);
    const batch = parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_TEXT, 0, 1, 0, 0]], stringEntry("hi!")));
    applyBatch(batch, r);
    expect(span.textContent).toBe("hi!");
  });

  it("applies SET_TEXT to a text field's input", () => {
    const tf = document.createElement("label");
    tf.className = "pathland-textfield";
    const input = document.createElement("input");
    input.type = "text";
    tf.appendChild(input);
    const r = renderer();
    r.byId.set(5, tf);
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_TEXT, 0, 5, 0, 0]], stringEntry("ab"))), r);
    expect(input.value).toBe("ab");
  });

  it("applies SELECTED to a toggle checkbox", () => {
    const toggle = document.createElement("label");
    toggle.className = "pathland-toggle";
    const box = document.createElement("input");
    box.type = "checkbox";
    toggle.appendChild(box);
    const r = renderer();
    r.byId.set(4, toggle);
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, 1, 0, 4, (0 << 16) | PROP_SELECTED, 1]])), r);
    expect(box.checked).toBe(true);
  });

  it("applies VALUE to a slider", () => {
    const slider = document.createElement("label");
    slider.className = "pathland-slider";
    const range = document.createElement("input");
    range.type = "range";
    slider.appendChild(range);
    const r = renderer();
    r.byId.set(6, slider);
    const bits = new Uint32Array(new Float32Array([0.75]).buffer)[0]!;
    applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, 1, 0, 6, (0 << 16) | PROP_VALUE, bits]])), r);
    expect(range.value).toBe("0.75");
  });

  it("suppresses VALUE while a slider is being dragged (in-flight)", () => {
    const slider = document.createElement("label");
    slider.className = "pathland-slider";
    const range = document.createElement("input");
    range.type = "range";
    range.value = "0.3";
    slider.appendChild(range);
    const r = renderer();
    r.byId.set(6, slider);
    const bits = new Uint32Array(new Float32Array([0.75]).buffer)[0]!;
    const batch = () =>
      parseBatch(buildBatch([[CAT_PARAMETER, 1, 0, 6, (0 << 16) | PROP_VALUE, bits]]));

    // While the drag is in flight the server echo must not move the thumb.
    markRangeInFlight(range);
    applyBatch(batch(), r);
    expect(range.value).toBe("0.3");

    // On release, inbound VALUE applies again.
    clearInFlightRange();
    applyBatch(batch(), r);
    expect(range.value).toBe("0.75");
  });
});

describe("applyBatch · TREE", () => {
  it("builds a stack: create nodes, insert, then set text", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch(
        [
          [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_VSTACK],
          [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_TEXT],
          [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2],
          [CAT_PARAMETER, CMD_SET_TEXT, 0, 2, 0],
        ],
        stringEntry("x"),
      ),
    );
    applyBatch(batch, r);
    const stack = r.byId.get(1) as HTMLElement;
    expect(stack).toBeInstanceOf(HTMLDivElement);
    expect(stack.style.display).toBe("flex");
    expect(stack.style.flexDirection).toBe("column");
    expect(r.byId.get(2)?.textContent).toBe("x");
    expect(stack.children).toHaveLength(1);
    expect(stack.firstElementChild?.getAttribute("data-pathland-id")).toBe("2");
  });

  it("removes a node from the DOM", () => {
    const root = document.createElement("div");
    const button = document.createElement("button");
    button.setAttribute("data-pathland-id", "9");
    root.appendChild(button);
    const r = renderer();
    r.byId.set(9, button);
    applyBatch(parseBatch(buildBatch([[CAT_TREE, 2, 0, 9, 0, 0]])), r);
    expect(root.childNodes).toHaveLength(0);
