    applyBatch(
      parseBatch(
        buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_U32 << 16) | PROP_NAV_DEPTH, 1]]),
      ),
      r,
    );
    expect(slot.querySelector(".pathland-nav-back")).toBeNull();
  });

  it("never draws a back button on a Custom-chrome slot", () => {
    const r = renderer();
    const slot = document.createElement("div");
    slot.setAttribute("data-pathland-id", "1");
    slot.setAttribute("data-pathland-route", "/users");
    r.byId.set(1, slot);

    applyBatch(
      parseBatch(
        buildBatch([
          [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_F32 << 16) | PROP_NAV_CHROME, f32bits(1)],
          [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_U32 << 16) | PROP_NAV_DEPTH, 3],
        ]),
      ),
      r,
    );
    expect(slot.querySelector(".pathland-nav-back")).toBeNull();
    expect(slot.getAttribute("data-pathland-nav-chrome")).toBe("custom");
  });

  it("hydrates a default back button from the SSR HTML (data-pathland-depth)", () => {
    const r = renderer();
    const slot = document.createElement("div");
    slot.setAttribute("data-pathland-id", "1");
    slot.setAttribute("data-pathland-route", "/users");
    slot.setAttribute("data-pathland-depth", "2");
    r.byId.set(1, slot);

    updateNavBackButtons(r);
    expect(slot.querySelector(".pathland-nav-back")).not.toBeNull();
  });

  it("wraps children inserted into a ZStack in a grid-area cell shell (runtime overlap)", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_ZSTACK],
        [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_TEXT],
        [CAT_TREE, CMD_CREATE_NODE, 0, 3, COMPONENT_BUTTON],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 3],
      ]),
    );
    applyBatch(batch, r);
    const zstack = r.byId.get(1) as HTMLElement;
    const first = r.byId.get(2) as HTMLElement;
    const second = r.byId.get(3) as HTMLElement;
    // Mirrors the Rust SSR renderer's per-child
    // `<div style="grid-area:1/1;justify-self:...;align-self:...">` shell
    // (overlap in the ZSTACK grid's single cell). The shell has no explicit
    // width/height: a FILL child stretches to the track (align-self:stretch),
    // a Hug child keeps its content size and is positioned per ALIGNMENT.
    const wrappers = Array.from(zstack.children).filter((el) => el instanceof HTMLElement);
    expect(wrappers).toHaveLength(2);
    for (const wrapper of wrappers) {
      const el = wrapper as HTMLElement;
      expect(el.style.gridArea).toBe("1/1");
      expect(el.style.width).toBe("");
      expect(el.style.height).toBe("");
      expect(el.tagName).toBe("DIV");
    }
    expect(zstack.contains(first)).toBe(true);
    expect(zstack.contains(second)).toBe(true);
    expect(first.parentElement).not.toBe(zstack);
    // Tracks are minmax(0,1fr): a bare 1fr track's auto minimum is the largest
    // child's min-content size, which would overflow a short viewport and push
    // an end-aligned child (a player bar) out of view.
    expect(zstack.style.gridTemplateColumns).toBe("minmax(0,1fr)");
    expect(zstack.style.gridTemplateRows).toBe("minmax(0,1fr)");
  });

  it("splits a ZStack 2D ALIGNMENT into justify-self/align-self (topTrailing)", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_ZSTACK],
        [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_F32 << 16) | PROP_ALIGNMENT, f32bits(ALIGN_TOP_TRAILING)],
        [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_TEXT],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2],
      ]),
    );
    applyBatch(batch, r);
    const zstack = r.byId.get(1) as HTMLElement;
    expect(zstack.style.justifyItems).toBe("end"); // horizontal end
    expect(zstack.style.alignItems).toBe("start"); // vertical start
    const shell = zstack.children[0] as HTMLElement;
    expect(shell.style.justifySelf).toBe("end");
    expect(shell.style.alignSelf).toBe("start");
  });

  it("applies a ZStack child's Z_INDEX to its wrapper shell (draw-order override)", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_ZSTACK],
        [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_TEXT],
        [CAT_TREE, CMD_CREATE_NODE, 0, 3, COMPONENT_TEXT],
        // The FIRST child has z-index 5 (F32 — the DSL wire type): its shell
        // must carry it so it draws above the later sibling.
        [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 2, (VAL_F32 << 16) | PROP_Z_INDEX, f32bits(5)],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 3],
      ]),
    );
    applyBatch(batch, r);
    const zstack = r.byId.get(1) as HTMLElement;
    expect(zstack.style.isolation).toBe("isolate"); // scopes shell z-indexes
    const child = r.byId.get(2) as HTMLElement;
    const shell = child.parentElement as HTMLElement;
    expect(shell.parentElement).toBe(zstack); // it is the ZSTACK's grid shell
    expect(shell.style.zIndex).toBe("5");
    expect(child.style.zIndex).toBe("5");
    const sibling = r.byId.get(3) as HTMLElement;
    expect((sibling.parentElement as HTMLElement).style.zIndex).toBe("0");
  });

  it("mirrors GRID_COLUMNS/GRID_ROWS into track templates (never pixel sizes) and wraps cells", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_GRID],
        [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_F32 << 16) | PROP_GRID_COLUMNS, f32bits(2)],
        [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_F32 << 16) | PROP_GRID_ROWS, f32bits(3)],
        [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_TEXT],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2],
      ]),
    );
    applyBatch(batch, r);
    const grid = r.byId.get(1) as HTMLElement;
    expect(grid.style.gridTemplateColumns).toBe("repeat(2,minmax(0,1fr))");
    expect(grid.style.gridTemplateRows).toBe("repeat(3,minmax(0,1fr))");
    expect(grid.style.width).not.toBe("2px"); // a count, never a pixel box
    expect(grid.style.height).not.toBe("3px");
    expect(grid.style.justifyItems).toBe("start");
    expect(grid.style.alignItems).toBe("start");
    // A Hug cell is wrapped in an auto-placed shell positioned at start.
    const cell = r.byId.get(2) as HTMLElement;
    const wrapper = cell.parentElement as HTMLElement;
    expect(wrapper.tagName).toBe("DIV");
    expect(wrapper.style.justifySelf).toBe("start");
    expect(wrapper.style.alignSelf).toBe("start");
  });

  it("LAZY_HGRID reads GRID_ROWS (the fixed track) and ignores GRID_COLUMNS", () => {
    const r = renderer();
    const batch = parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_LAZY_HGRID],
        [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_F32 << 16) | PROP_GRID_COLUMNS, f32bits(2)],
        [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_F32 << 16) | PROP_GRID_ROWS, f32bits(3)],
      ]),
    );
    applyBatch(batch, r);
    const grid = r.byId.get(1) as HTMLElement;
    expect(grid.style.gridTemplateRows).toBe("repeat(3,minmax(0,1fr))");
    expect(grid.style.gridTemplateColumns).toBe("");
    expect(grid.style.gridAutoFlow).toBe("column");
    expect(grid.style.gridAutoColumns).toBe("minmax(0,1fr)");
  });

  it("morphs a ProgressView between spinner and determinate progress", () => {
    const r = renderer();
    applyBatch(
      parseBatch(
        buildBatch([
          [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_PROGRESS_VIEW],
          [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_U8 << 16) | PROP_IS_INDETERMINATE, 1],
        ]),
      ),
      r,
    );
    const spinner = r.byId.get(1) as HTMLElement;
    expect(spinner.classList.contains("pathland-spinner")).toBe(true);
    expect(spinner.tagName).toBe("DIV");

    applyBatch(
      parseBatch(
        buildBatch([
          [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_F32 << 16) | PROP_PROGRESS, f32bits(0.5)],
        ]),
      ),
      r,
    );
    const progress = r.byId.get(1);
    expect(progress).toBeInstanceOf(HTMLProgressElement);
    expect((progress as HTMLProgressElement).value).toBeCloseTo(0.5);
    expect((progress as HTMLProgressElement).max).toBe(1);
  });
});

describe("applyBatch · semantic roles (generated role-spec)", () => {
  const roleBatch = (id: number, component: number, role: number) =>
    buildBatch([
      [CAT_TREE, CMD_CREATE_NODE, 0, id, component],
