      parseBatch(
        buildBatch(
          [
            [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_ICON],
            [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_STRING << 16) | PROP_ICON_NAME, 0],
            [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_STRING << 16) | PROP_LABEL, 16],
